const QUESTIONS = [
  // ---------------- Chapter 3 — Tools of the Laboratory ----------------
  { id: "ch3-001", chapter: "3", topic: "Culturing basics", question: "Which of the following is NOT one of the Five I's of culturing microbes?", choices: ["Inoculation", "Incubation", "Illumination", "Isolation"], answer: 2, explanation: "The Five I's are Inoculation, Incubation, Isolation, Inspection, and Identification." },
  { id: "ch3-002", chapter: "3", topic: "Culturing basics", question: "What is the difference between a colony and a cell?", choices: ["A colony is a visible mass of cells; a cell is a single microbe", "A colony is a single cell; a cell is a visible mass", "They are the same thing", "A colony only forms from viruses"], answer: 0, explanation: "A colony is a visible cluster of many cells, usually descended from one original cell." },
  { id: "ch3-003", chapter: "3", topic: "Culturing basics", question: "Why is an isolated colony (not touching other colonies) likely a pure culture?", choices: ["It grew from a single cell or cell cluster", "It contains many different species", "It only grows on selective media", "It has been sterilized"], answer: 0, explanation: "An isolated colony usually arises from one cell, so all its cells are genetically identical." },
  { id: "ch3-004", chapter: "3", topic: "Culturing basics", question: "Which technique is commonly used to generate isolated colonies?", choices: ["Streak plate", "Gram staining", "Autoclaving", "Negative staining"], answer: 0, explanation: "The streak plate technique spreads cells thinly so single cells grow into separate colonies." },
  { id: "ch3-005", chapter: "3", topic: "Media", question: "What ingredient is added to a liquid broth recipe to make it solid?", choices: ["Agar", "Peptone", "Yeast extract", "Salt"], answer: 0, explanation: "Agar is a solidifying agent; less agar gives semisolid media and none gives liquid broth." },
  { id: "ch3-006", chapter: "3", topic: "Media", question: "Which type of media contains ingredients that inhibit the growth of some microbes while allowing others to grow?", choices: ["Selective media", "Differential media", "General-purpose media", "Defined media"], answer: 0, explanation: "Selective media suppress unwanted microbes (for example with salt, dyes, or antibiotics)." },
  { id: "ch3-007", chapter: "3", topic: "Media", question: "Which type of media allows visually distinguishing between different microbes based on a reaction or color change?", choices: ["Differential media", "Selective media", "Defined media", "Enrichment media"], answer: 0, explanation: "Differential media contain indicators that show differences in microbial metabolism." },
  { id: "ch3-008", chapter: "3", topic: "Media", question: "MacConkey agar contains bile salts and crystal violet (inhibit Gram-positives) and lactose with a pH indicator. It is best described as:", choices: ["Both selective and differential", "Selective only", "Differential only", "Neither selective nor differential"], answer: 0, explanation: "Bile salts and crystal violet select against Gram-positives; lactose plus a pH indicator differentiates lactose fermenters." },
  { id: "ch3-009", chapter: "3", topic: "Media", question: "A medium made of beef extract and peptone, whose exact chemical composition is unknown, is:", choices: ["Complex (undefined)", "Defined", "Differential only", "Always selective"], answer: 0, explanation: "Media with extracts or digests of unknown exact composition are complex (undefined)." },
  { id: "ch3-010", chapter: "3", topic: "Media", question: "A medium in which every ingredient and its exact amount is known is called:", choices: ["Defined (chemically defined)", "Complex", "Enrichment", "Semisolid"], answer: 0, explanation: "Defined media have a known chemical composition." },
  { id: "ch3-011", chapter: "3", topic: "Media", question: "Enrichment media are used to:", choices: ["Encourage growth of a particular microbe that is present in low numbers", "Kill all bacteria", "Stain bacteria", "Sterilize samples"], answer: 0, explanation: "Enrichment media supply nutrients that favor a particular organism so it outgrows others." },
  { id: "ch3-012", chapter: "3", topic: "Microscopy", question: "Which statement correctly contrasts light and electron microscopy?", choices: ["Light microscopes use visible light and glass lenses; electron microscopes use electron beams", "Light microscopes use electron beams; electron microscopes use visible light", "Both use electron beams", "Electron microscopes have lower resolution than light microscopes"], answer: 0, explanation: "Electron microscopes use electrons and electromagnets, giving much higher resolution." },
  { id: "ch3-013", chapter: "3", topic: "Microscopy", question: "A student uses a 10X ocular lens and the 100X oil immersion objective. What is the total magnification?", choices: ["1000X", "110X", "100X", "400X"], answer: 0, explanation: "Total magnification = ocular power x objective power = 10 x 100 = 1000X." },
  { id: "ch3-014", chapter: "3", topic: "Microscopy", question: "Why is immersion oil used with the 100X objective?", choices: ["It reduces light refraction/loss so more light enters the lens, improving resolution", "It stains the bacteria", "It kills the bacteria", "It cools the specimen"], answer: 0, explanation: "Oil has a refractive index close to glass, preventing light from bending away from the lens." },
  { id: "ch3-015", chapter: "3", topic: "Microscopy", question: "All microscopes require lenses and which of the following?", choices: ["A source of radiation (light or electrons)", "Immersion oil", "Stained specimens", "A vacuum"], answer: 0, explanation: "Every microscope needs lenses to magnify and a radiation source to illuminate the specimen." },
  { id: "ch3-016", chapter: "3", topic: "Microscopy", question: "Which microscope produces bright cells against a dark background and is useful for live, unstained specimens?", choices: ["Darkfield", "Brightfield", "TEM", "SEM"], answer: 0, explanation: "Darkfield scatters light off the specimen only, so cells appear bright on a dark field." },
  { id: "ch3-017", chapter: "3", topic: "Microscopy", question: "Which microscope uses fluorescent dyes (fluorochromes) and ultraviolet light?", choices: ["Fluorescence microscope", "Brightfield microscope", "Phase-contrast microscope", "Darkfield microscope"], answer: 0, explanation: "Fluorescence microscopy excites dyes with UV light so labeled structures glow." },
  { id: "ch3-018", chapter: "3", topic: "Microscopy", question: "Which microscope allows viewing internal structures of live, unstained cells by exploiting differences in refractive index?", choices: ["Phase-contrast", "Brightfield", "SEM", "Darkfield"], answer: 0, explanation: "Phase-contrast converts small density differences within cells into contrast." },
  { id: "ch3-019", chapter: "3", topic: "Microscopy", question: "Which electron microscope produces a three-dimensional image of a specimen's surface?", choices: ["Scanning electron microscope (SEM)", "Transmission electron microscope (TEM)", "Brightfield microscope", "Phase-contrast microscope"], answer: 0, explanation: "SEM scans the surface for a 3D-looking image; TEM images thin sections to show internal structure." },
  { id: "ch3-020", chapter: "3", topic: "Microscopy", question: "Which electron microscope is used to view the internal structure of very thin sections of a specimen?", choices: ["Transmission electron microscope (TEM)", "Scanning electron microscope (SEM)", "Darkfield microscope", "Brightfield microscope"], answer: 0, explanation: "In TEM, electrons pass through a thin section to reveal internal detail." },
  { id: "ch3-021", chapter: "3", topic: "Staining", question: "Why is staining usually required when using a brightfield microscope?", choices: ["Cells are nearly transparent and lack contrast", "Cells are too large to see", "Stains make cells larger", "Stains sterilize the slide"], answer: 0, explanation: "Unstained bacteria are colorless and hard to see against a bright background." },
  { id: "ch3-022", chapter: "3", topic: "Staining", question: "A simple stain uses a single dye. What information does it mainly provide?", choices: ["Cell shape, size, and arrangement", "Cell wall type", "Presence of mycolic acid", "Presence of a capsule only"], answer: 0, explanation: "Simple stains color all cells the same, revealing morphology and arrangement." },
  { id: "ch3-023", chapter: "3", topic: "Staining", question: "In a negative stain, which part of the preparation is colored?", choices: ["The background", "The cell itself", "Only the nucleus", "Only the cell wall"], answer: 0, explanation: "An acidic dye is repelled by the negatively charged cell, leaving the cell clear against a dark background." },
  { id: "ch3-024", chapter: "3", topic: "Staining", question: "Which two procedures are differential staining techniques?", choices: ["Gram stain and acid-fast stain", "Simple stain and negative stain", "Gram stain and simple stain", "Acid-fast stain and negative stain"], answer: 0, explanation: "Differential stains use multiple reagents to separate cell types: Gram and acid-fast." },
  { id: "ch3-025", chapter: "3", topic: "Staining", question: "What does the Gram stain differentiate?", choices: ["Cell wall types (Gram-positive vs Gram-negative)", "Presence of mycolic acid", "Live from dead cells", "Presence of endospores only"], answer: 0, explanation: "The Gram stain separates bacteria by cell wall structure." },
  { id: "ch3-026", chapter: "3", topic: "Staining", question: "What does the acid-fast stain test for?", choices: ["Waxy mycolic acid in the cell wall", "Thick peptidoglycan", "Flagella", "Capsules"], answer: 0, explanation: "Acid-fast bacteria such as Mycobacterium retain the primary stain because of mycolic acids." },

  // ---------------- Chapter 3 — From lecture slides (Ch 3 PowerPoint) ----------------
  { id: "ch3-027", chapter: "3", topic: "Culturing basics", question: "In culturing, what is the inoculum?", choices: ["The microbes intentionally added into the medium", "The nutrient mix", "The visible growth", "The sterile technique"], answer: 0, explanation: "Inoculation is adding the inoculum to the medium; the visible growth that results is the culture." },
  { id: "ch3-028", chapter: "3", topic: "Culturing basics", question: "What is a culture?", choices: ["Visible growth of microbes in or on a medium (colony, turbidity, etc.)", "The nutrient mix itself", "A single microscopic cell", "A sterilized instrument"], answer: 0, explanation: "A medium is the nutrient mix; the culture is the growth in or on it." },
  { id: "ch3-029", chapter: "3", topic: "Culturing basics", question: "What is a pure culture compared with a mixed culture?", choices: ["A pure culture has one species; a mixed culture has two or more", "A pure culture has no microbes", "A mixed culture has only one species", "They are the same"], answer: 0, explanation: "Pure cultures are needed to study or identify a single species." },
  { id: "ch3-030", chapter: "3", topic: "Culturing basics", question: "What is asepsis?", choices: ["The absence of contamination by unwanted organisms", "The presence of all microbes", "A type of medium", "A staining method"], answer: 0, explanation: "Aseptic technique (sterile technique) uses sterile media and tools to prevent contamination." },
  { id: "ch3-031", chapter: "3", topic: "Colonies", question: "A bacterial colony is best described as:", choices: ["A pile of cells visible to the naked eye, typically containing about a billion cells", "A single microscopic cell", "A virus particle", "A medium"], answer: 0, explanation: "A colony is macroscopic; the cell is microscopic." },
  { id: "ch3-032", chapter: "3", topic: "Colonies", question: "Why should all cells in an isolated colony be genetically identical?", choices: ["They descend from one ancestral cell and bacteria reproduce asexually", "Bacteria reproduce sexually", "Mutations never happen", "They were stained the same"], answer: 0, explanation: "Binary fission produces identical copies of the ancestral cell." },
  { id: "ch3-033", chapter: "3", topic: "Media", question: "How does semisolid medium differ from solid medium?", choices: ["It contains less agar", "It contains more agar", "It contains no nutrients", "It is always selective"], answer: 0, explanation: "Liquid broth has no agar, semisolid has a little agar, and solid has more." },
  { id: "ch3-034", chapter: "3", topic: "Media", question: "Complex (chemically undefined) media typically contain:", choices: ["Extracts of yeast, meat, or plants and peptones", "Only pure chemicals with known formulas", "Only agar and water", "Only antibiotics"], answer: 0, explanation: "Examples are nutrient agar or broth and tryptic soy agar (TSA) or broth (TSB). Peptones are partially digested proteins." },
  { id: "ch3-035", chapter: "3", topic: "Media", question: "In chemically defined media, the amount of each element is:", choices: ["Known and consistent among batches", "Unknown", "Variable between batches", "Provided only by extracts"], answer: 0, explanation: "All ingredients have specific molecular formulas." },
  { id: "ch3-036", chapter: "3", topic: "Media", question: "General-purpose media such as TSA are used to:", choices: ["Grow a wide variety of non-fastidious microbes without selecting for a group", "Grow only fungi", "Test for one metabolic trait", "Grow only fastidious microbes"], answer: 0, explanation: "Not every microbe grows on TSA, because fastidious microbes need richer media." },
  { id: "ch3-037", chapter: "3", topic: "Media", question: "True or false: any microbe can be cultured on TSA.", choices: ["False; fastidious microbes need enriched media", "True", "True, but only fungi", "False; only viruses fail"], answer: 0, explanation: "TSA grows many non-fastidious microbes but not all." },
  { id: "ch3-038", chapter: "3", topic: "Media", question: "Blood agar is an example of which media type, good for fastidious microbes?", choices: ["Enrichment media", "Selective media only", "Defined media", "Semisolid media"], answer: 0, explanation: "Enrichment media supply extra nutrients for demanding microbes." },
  { id: "ch3-039", chapter: "3", topic: "Media", question: "Sabouraud's agar (pH 5.6) is selective for which group?", choices: ["Fungi", "Gram-negative bacteria", "Viruses", "Protozoa"], answer: 0, explanation: "The low pH selects for fungi and against most bacteria." },
  { id: "ch3-040", chapter: "3", topic: "Media", question: "Which ingredients may be added to make a medium selective?", choices: ["High salt, dyes, antibiotics, or an unusual pH", "Extra water", "Extra agar only", "Peptone only"], answer: 0, explanation: "These inhibit unwanted microbes while allowing the target group to grow." },
  { id: "ch3-041", chapter: "3", topic: "Media", question: "Phenol red media are differential because:", choices: ["The color changes depending on whether a microbe can ferment the sugar", "They stop all growth", "They contain antibiotics", "They are solid"], answer: 0, explanation: "Differential media test for a specific trait and may allow preliminary identification." },
  { id: "ch3-042", chapter: "3", topic: "Media", question: "Mannitol salt agar (MSA) lets only salt-tolerant organisms grow, and colonies are yellow or pink depending on mannitol fermentation. It is:", choices: ["Both selective and differential", "Selective only", "Differential only", "Neither"], answer: 0, explanation: "High salt is selective; the color difference is differential." },
  { id: "ch3-043", chapter: "3", topic: "Media", question: "Two organisms are placed on two plates. Only one organism grows on Plate A, and both grow on Plate B. Which is selective?", choices: ["Plate A", "Plate B", "Both", "Neither"], answer: 0, explanation: "A selective medium allows only certain microbes to grow; a general-purpose medium lets both grow." },
  { id: "ch3-044", chapter: "3", topic: "Five I's", question: "What is incubation?", choices: ["A period of time to allow cell growth in a controlled environment (temperature, pH, oxygen)", "Adding microbes to medium", "Separating species", "Staining cells"], answer: 0, explanation: "Incubation is the second of the Five I's." },
  { id: "ch3-045", chapter: "3", topic: "Five I's", question: "Isolation in the Five I's means:", choices: ["Separating one species from another so individual cells grow into colonies", "Looking at colonies", "Identifying to species", "Adding the inoculum"], answer: 0, explanation: "Subculturing from isolated colonies develops pure cultures; the streak plate is one method." },
  { id: "ch3-046", chapter: "3", topic: "Five I's", question: "In the inspection step, colonies are observed ___ and cells are observed ___.", choices: ["Macroscopically; microscopically", "Microscopically; macroscopically", "Both macroscopically", "Both microscopically"], answer: 0, explanation: "Colonies can be seen with the naked eye; individual cells need a microscope." },
  { id: "ch3-047", chapter: "3", topic: "Five I's", question: "The fifth I, identification, aims to identify a microbe to which level?", choices: ["Species (and possibly strain)", "Domain only", "Kingdom only", "Phylum only"], answer: 0, explanation: "Identification follows inspection." },
  { id: "ch3-048", chapter: "3", topic: "Microscopy", question: "What total magnification results from a 10X ocular and the 40X high-power objective?", choices: ["400X", "40X", "100X", "4000X"], answer: 0, explanation: "Objectives are 4X scanning, 10X low, 40X high, and 100X oil immersion; the ocular is 10X." },
  { id: "ch3-049", chapter: "3", topic: "Microscopy", question: "What is resolution?", choices: ["The ability to distinguish two different points as separate", "How large the image appears", "The brightness of the lamp", "The thickness of the slide"], answer: 0, explanation: "Magnification makes things bigger; resolution makes them clearer." },
  { id: "ch3-050", chapter: "3", topic: "Microscopy", question: "Which of these increases resolution?", choices: ["Using a higher numerical aperture objective, oil with the 100X objective, or a shorter wavelength", "Using a longer wavelength", "Removing the oil", "Opening the diaphragm fully"], answer: 0, explanation: "Turning up the lamp but partially closing the diaphragm also helps." },
  { id: "ch3-051", chapter: "3", topic: "Microscopy", question: "What is the approximate limit of resolution of a light microscope?", choices: ["About 0.2 micrometers", "About 0.001 micrometers", "About 20 micrometers", "About 2 millimeters"], answer: 0, explanation: "Anything smaller, such as viruses, requires an electron microscope." },
  { id: "ch3-052", chapter: "3", topic: "Microscopy", question: "Which is true of brightfield microscopy?", choices: ["It uses visible light, is inexpensive and easy, and often requires fixing and staining", "It uses electron beams", "It uses UV light", "It produces 3D images"], answer: 0, explanation: "Its resolution is about 0.2 micrometers." },
  { id: "ch3-053", chapter: "3", topic: "Microscopy", question: "How does fluorescence microscopy work?", choices: ["A fluorochrome absorbs UV light and emits visible light", "Electrons scan the surface", "Light is scattered from the sides only", "Phase shifts are converted to contrast"], answer: 0, explanation: "Filters protect the eye from UV." },
  { id: "ch3-054", chapter: "3", topic: "Microscopy", question: "Immunofluorescence uses:", choices: ["Fluorescently labeled antibodies specific for an organism or protein", "Gold coating", "Heavy metal stains", "Phenol red"], answer: 0, explanation: "It is one way to detect a microbe of interest in a sample." },
  { id: "ch3-055", chapter: "3", topic: "Microscopy", question: "You mix a fluorescent antibody specific for M. tuberculosis with a sputum sample and see no fluorescent cells. What is one explanation?", choices: ["The bacterium is not present in the sample", "The bacterium is too large", "The antibody is attached to the wrong lens", "Fluorescence needs electrons"], answer: 0, explanation: "The antibody binds only its target; no binding means no fluorescence." },
  { id: "ch3-056", chapter: "3", topic: "Microscopy", question: "Which is true of electron microscopes?", choices: ["They use electron beams and electromagnetic lenses, and images are black and white", "They use visible light and glass lenses", "They produce color images", "They view living specimens"], answer: 0, explanation: "The specimen is fixed; any color seen in micrographs is added later." },
  { id: "ch3-057", chapter: "3", topic: "Microscopy", question: "True or false: electron micrographs provide cellular detail in color.", choices: ["False", "True", "True for SEM only", "True for TEM only"], answer: 0, explanation: "Electron micrographs are black and white." },
  { id: "ch3-058", chapter: "3", topic: "Microscopy", question: "Why can electron microscopes resolve smaller objects than light microscopes?", choices: ["Electrons have a much shorter wavelength", "Electrons are brighter", "They use oil", "They use larger lenses"], answer: 0, explanation: "Shorter wavelength gives better resolution." },
  { id: "ch3-059", chapter: "3", topic: "Microscopy", question: "Which describes TEM sample preparation and images?", choices: ["Very thin sections (~100 nm) with heavy metal stains, giving 2D images of internal structure", "Gold-coated whole cells with 3D surface images", "Living cells in water", "Unstained smears"], answer: 0, explanation: "TEM is time-intensive and fixation can distort or add artifacts." },
  { id: "ch3-060", chapter: "3", topic: "Microscopy", question: "Which describes SEM?", choices: ["No sectioning; the specimen is coated with gold, giving 3D images of surface features", "Thin sections with heavy metals", "Uses UV light", "Shows internal structure"], answer: 0, explanation: "SEM collects electrons knocked from the specimen's surface." },
  { id: "ch3-061", chapter: "3", topic: "Microscopy", question: "Which type of microscope is used in the lab this semester?", choices: ["Brightfield", "SEM", "Fluorescent", "TEM"], answer: 0, explanation: "Students prepare stained smears for brightfield microscopy in lab." },
  { id: "ch3-062", chapter: "3", topic: "Staining", question: "What is the usual order for preparing a stained smear?", choices: ["Prepare smear, air dry, fix with heat or methyl alcohol, then stain", "Stain, then air dry, then fix", "Fix, then stain, then smear", "Heat, then dry, then smear"], answer: 0, explanation: "Fixing attaches the specimen to the slide." },
  { id: "ch3-063", chapter: "3", topic: "Staining", question: "Which pair lists basic stains?", choices: ["Crystal violet, methylene blue, safranin", "Eosin, nigrosin, acid fuchsin", "Iodine, ethanol, water", "Carbol fuchsin only"], answer: 0, explanation: "In basic stains the positive ion is the chromophore." },
  { id: "ch3-064", chapter: "3", topic: "Staining", question: "Most bacteria have a slightly negative surface charge. Which chromophore binds most strongly?", choices: ["Basic (positively charged)", "Acidic (negatively charged)", "Neutral", "Neither"], answer: 0, explanation: "Opposite charges attract; acidic stains are repelled." },
  { id: "ch3-065", chapter: "3", topic: "Staining", question: "A negative stain uses which kind of stain, and is it fixed?", choices: ["An acidic stain; no fixing needed", "A basic stain; heat fixing required", "Two stains; fixing required", "A fluorescent stain; fixing required"], answer: 0, explanation: "Cells repel the stain, so the background is stained. Shape and size are not distorted." },
  { id: "ch3-066", chapter: "3", topic: "Staining", question: "How does a simple stain differ from a differential stain?", choices: ["A simple stain uses one basic stain; a differential stain uses more than one and distinguishes groups", "A simple stain uses two stains", "A differential stain uses only one dye", "They are identical"], answer: 0, explanation: "Gram and acid-fast stains are differential." },
  { id: "ch3-067", chapter: "3", topic: "Staining", question: "How does a negative stain differ from darkfield microscopy?", choices: ["A negative stain colors the background with a dye; darkfield needs no stain and shows bright cells on a dark field by light scattering", "They are the same", "Darkfield uses dye; negative stain uses electrons", "Negative staining uses UV light"], answer: 0, explanation: "Both give cells that contrast with the background, but by different methods." },

  // ---------------- Chapter 4 — Bacteria & Archaea Cell Structures ----------------
  { id: "ch4-001", chapter: "4", topic: "Glycocalyx", question: "What is a glycocalyx?", choices: ["A sticky layer of polysaccharides/polypeptides outside the cell wall", "A protein-making organelle", "A DNA-containing region", "A type of flagellum"], answer: 0, explanation: "The glycocalyx is a sugar-rich coating outside the cell wall." },
  { id: "ch4-002", chapter: "4", topic: "Glycocalyx", question: "The glycocalyx can take which two forms?", choices: ["Slime layer or capsule", "Flagellum or pilus", "Nucleoid or plasmid", "Endospore or cyst"], answer: 0, explanation: "A loosely attached glycocalyx is a slime layer; a firmly attached, organized one is a capsule." },
  { id: "ch4-003", chapter: "4", topic: "Glycocalyx", question: "Why is a bacterial capsule medically important?", choices: ["It helps bacteria avoid phagocytosis, increasing virulence", "It kills white blood cells directly", "It makes bacteria susceptible to antibiotics", "It produces toxins"], answer: 0, explanation: "Capsules make it harder for immune cells to engulf bacteria." },
  { id: "ch4-004", chapter: "4", topic: "Cytoplasmic structures", question: "What is the nucleoid?", choices: ["The region of the cytoplasm containing the bacterial chromosome", "A membrane-bound nucleus", "A ribosome subunit", "An extrachromosomal plasmid"], answer: 0, explanation: "Prokaryotes lack a membrane-bound nucleus; their DNA is in the nucleoid region." },
  { id: "ch4-005", chapter: "4", topic: "Cytoplasmic structures", question: "Plasmids are best described as:", choices: ["Small circular DNA molecules separate from the chromosome, often carrying traits like antibiotic resistance", "Protein-making machines", "Storage granules", "Thick protective coats"], answer: 0, explanation: "Plasmids are extra, nonessential DNA that can carry resistance genes." },
  { id: "ch4-006", chapter: "4", topic: "Cytoplasmic structures", question: "What is the function of ribosomes in bacteria?", choices: ["Protein synthesis", "DNA storage", "ATP storage", "Cell motility"], answer: 0, explanation: "Ribosomes translate mRNA into protein." },
  { id: "ch4-007", chapter: "4", topic: "Endospores", question: "Which two bacterial genera can form endospores?", choices: ["Bacillus and Clostridium", "Escherichia and Salmonella", "Streptococcus and Staphylococcus", "Vibrio and Pseudomonas"], answer: 0, explanation: "Bacillus and Clostridium are the endospore-forming genera covered." },
  { id: "ch4-008", chapter: "4", topic: "Endospores", question: "Which is a key trait of endospores?", choices: ["Dormant and highly resistant to heat, chemicals, and desiccation", "Actively reproducing", "Easily killed by boiling", "A means of reproduction"], answer: 0, explanation: "Endospores are survival structures, not reproductive ones." },
  { id: "ch4-009", chapter: "4", topic: "Endospores", question: "How does a vegetative cell differ from an endospore?", choices: ["A vegetative cell is metabolically active and can grow and divide", "A vegetative cell is dormant", "A vegetative cell is more heat resistant", "A vegetative cell has no DNA"], answer: 0, explanation: "Vegetative cells are the active form; endospores are dormant." },
  { id: "ch4-010", chapter: "4", topic: "Endospores", question: "What typically triggers a bacterium to form an endospore (sporulation)?", choices: ["Nutrient depletion or harsh conditions", "Abundant nutrients", "Presence of antibiotics only", "Warm, moist conditions"], answer: 0, explanation: "Stress such as starvation triggers sporulation; germination occurs when conditions improve." },
  { id: "ch4-011", chapter: "4", topic: "Endospores", question: "What is germination in the endospore life cycle?", choices: ["The endospore returns to an active vegetative cell when conditions are favorable", "A vegetative cell forms an endospore", "An endospore reproduces by budding", "The endospore releases toxin only"], answer: 0, explanation: "Germination ends dormancy and restores the vegetative cell." },
  { id: "ch4-012", chapter: "4", topic: "Endospore-formers", question: "Bacillus anthracis causes which disease?", choices: ["Anthrax", "Tetanus", "Botulism", "Pseudomembranous colitis"], answer: 0, explanation: "B. anthracis is the endospore-forming agent of anthrax." },
  { id: "ch4-013", chapter: "4", topic: "Endospore-formers", question: "Clostridium tetani causes tetanus. What is the key symptom?", choices: ["Spastic paralysis (muscle rigidity, lockjaw)", "Flaccid paralysis", "Watery diarrhea", "Black skin lesion"], answer: 0, explanation: "Tetanus toxin blocks inhibitory signals, causing sustained muscle contraction." },
  { id: "ch4-014", chapter: "4", topic: "Endospore-formers", question: "Clostridium botulinum toxin causes which key symptom?", choices: ["Flaccid paralysis", "Spastic paralysis", "Bloody diarrhea", "High fever and rash"], answer: 0, explanation: "Botulinum toxin blocks acetylcholine release, causing limp (flaccid) paralysis." },
  { id: "ch4-015", chapter: "4", topic: "Endospore-formers", question: "How does infant botulism differ from adult (foodborne) botulism?", choices: ["In infants, ingested spores germinate in the gut and produce toxin; in adults, preformed toxin is ingested", "Infants ingest preformed toxin; adults ingest spores", "Infant botulism is caused by a virus", "There is no difference"], answer: 0, explanation: "Infants lack a mature gut microbiota, so spores (for example from honey) can grow and make toxin." },
  { id: "ch4-016", chapter: "4", topic: "Endospore-formers", question: "Clostridioides (Clostridium) difficile infection most commonly follows:", choices: ["Antibiotic use that disrupts normal gut microbiota", "Eating undercooked beef", "A mosquito bite", "Inhaling spores from soil"], answer: 0, explanation: "Antibiotics reduce competing gut bacteria, allowing C. difficile to overgrow and produce toxins." },
  { id: "ch4-017", chapter: "4", topic: "Endospore-formers", question: "What are the main symptoms of C. difficile infection?", choices: ["Severe diarrhea and colitis", "Flaccid paralysis", "Lockjaw", "Skin black eschar"], answer: 0, explanation: "C. difficile toxins damage the colon, causing diarrhea and sometimes pseudomembranous colitis." },
  { id: "ch4-018", chapter: "4", topic: "FMT", question: "What does FMT stand for?", choices: ["Fecal microbial transplantation", "Fungal metabolism therapy", "Fast microbial treatment", "Fecal membrane transfer"], answer: 0, explanation: "FMT transfers stool microbiota from a healthy donor to a patient." },
  { id: "ch4-019", chapter: "4", topic: "FMT", question: "Why does FMT have such a high success rate for recurrent C. difficile?", choices: ["It restores a diverse, healthy microbiota that outcompetes C. difficile", "It kills C. difficile with antibiotics", "It destroys the toxin directly", "It removes the colon"], answer: 0, explanation: "A restored microbial community crowds out C. difficile." },
  { id: "ch4-020", chapter: "4", topic: "FMT", question: "Which is a risk or unknown of FMT?", choices: ["Possible transfer of pathogens and unknown long-term effects", "It causes antibiotic resistance in the donor", "It always causes anthrax", "It has no unknowns"], answer: 0, explanation: "Donor stool is complex, so infections and long-term effects are concerns." },
  { id: "ch4-021", chapter: "4", topic: "FMT", question: "What is the benefit of SER-109 compared with traditional FMT?", choices: ["It is a purified, standardized oral spore product with fewer unknowns", "It is delivered by colonoscopy", "It contains whole unscreened stool", "It is an antibiotic"], answer: 0, explanation: "SER-109 is a purified preparation of bacterial spores, making it more standardized and easier to deliver." },

  // ---------------- Chapter 4 — Cell wall diagram (from lecture slide) ----------------
  { id: "ch4-022", chapter: "4", topic: "Cell wall", question: "Which cell wall type has a thick peptidoglycan layer and NO outer membrane?", choices: ["Gram-positive", "Gram-negative", "Both Gram-positive and Gram-negative", "Neither"], answer: 0, explanation: "Gram-positive walls are thick peptidoglycan directly outside the cell membrane; Gram-negatives have a thin layer plus an outer membrane." },
  { id: "ch4-023", chapter: "4", topic: "Cell wall", question: "Which structure is found ONLY in Gram-negative bacteria?", choices: ["Outer membrane", "Peptidoglycan", "Cell membrane", "Cytoplasm"], answer: 0, explanation: "Only Gram-negative bacteria have an outer membrane outside the peptidoglycan layer." },
  { id: "ch4-024", chapter: "4", topic: "Cell wall", question: "Wall teichoic acids (WTA) and lipoteichoic acids (LTA) are found in which type of cell wall?", choices: ["Gram-positive", "Gram-negative", "Both equally", "Archaeal only"], answer: 0, explanation: "Teichoic acids are embedded in the thick peptidoglycan of Gram-positive bacteria." },
  { id: "ch4-025", chapter: "4", topic: "Cell wall", question: "What is the periplasm?", choices: ["The space between the cell membrane and outer membrane of Gram-negative bacteria, containing a thin peptidoglycan layer", "The cell's nucleus", "The inside of the cytoplasm", "The outermost slime layer"], answer: 0, explanation: "In the slide diagram, the periplasm lies between the cell membrane and the outer membrane." },
  { id: "ch4-026", chapter: "4", topic: "Cell wall", question: "Lipopolysaccharide (LPS) is a major component of:", choices: ["The outer membrane of Gram-negative bacteria", "The Gram-positive peptidoglycan layer", "The ribosome", "The nucleoid"], answer: 0, explanation: "LPS sits in the outer leaflet of the Gram-negative outer membrane." },
  { id: "ch4-027", chapter: "4", topic: "Cell wall", question: "In LPS, which part is embedded in the outer membrane and acts as an endotoxin?", choices: ["Lipid A", "O-antigen", "Core saccharide", "Teichoic acid"], answer: 0, explanation: "Lipid A anchors LPS in the membrane and triggers strong immune responses; the O-antigen extends outward." },
  { id: "ch4-028", chapter: "4", topic: "Cell wall", question: "Which is the correct order of LPS parts from the cell surface outward?", choices: ["Lipid A, core saccharide, O-antigen", "O-antigen, core saccharide, lipid A", "Core saccharide, lipid A, O-antigen", "Lipid A, O-antigen, core saccharide"], answer: 0, explanation: "Lipid A is in the membrane, the core saccharide attaches to it, and the O-antigen chain extends outward." },
  { id: "ch4-029", chapter: "4", topic: "Cell wall", question: "What is the role of outer membrane proteins (OMPs) such as porins in Gram-negative bacteria?", choices: ["They form channels that let small molecules cross the outer membrane", "They make ATP", "They synthesize peptidoglycan", "They replicate DNA"], answer: 0, explanation: "Porins are OMP channels for passage of small molecules." },

  // ---------------- Chapter 4 — From lecture slides (Ch 4 PowerPoint) ----------------
  { id: "ch4-030", chapter: "4", topic: "Cell morphology", question: "Which prokaryotic cell shape is a curved rod (comma shape)?", choices: ["Vibrio", "Coccobacillus", "Bacillus", "Coccus"], answer: 0, explanation: "The six common shapes are coccus, bacillus, coccobacillus, vibrio, spirillum, and spirochete; a vibrio is curved." },
  { id: "ch4-031", chapter: "4", topic: "Cell morphology", question: "What does pleomorphic mean, and which genus is an example?", choices: ["Variable cell shape; Mycoplasma", "Always spherical; Staphylococcus", "Forms endospores; Bacillus", "Always rod-shaped; Escherichia"], answer: 0, explanation: "Pleomorphic cells are shape-shifters. Mycoplasma lacks a cell wall." },
  { id: "ch4-032", chapter: "4", topic: "Cell morphology", question: "Pleomorphic bacteria such as Mycoplasma ___ a cell wall.", choices: ["Lack", "Have"], answer: 0, explanation: "Without a rigid wall, the cell shape is not fixed." },
  { id: "ch4-033", chapter: "4", topic: "Cell morphology", question: "A species' cell arrangement is determined by:", choices: ["The number of planes it divides in and whether daughter cells stay attached", "The Gram reaction", "The presence of a capsule", "The number of flagella"], answer: 0, explanation: "If daughter cells detach after division there is no arrangement." },
  { id: "ch4-034", chapter: "4", topic: "Cell morphology", question: "Which cell arrangements are possible only for coccus-shaped species?", choices: ["Tetrad, sarcina, and staphylo (division in 2 or more planes)", "Diplo and strepto", "Palisades and chains", "Only pairs"], answer: 0, explanation: "Bacilli can divide only across their short axis, so they have fewer possible arrangements." },
  { id: "ch4-035", chapter: "4", topic: "Cell morphology", question: "A coccus species divides in one plane and the cells remain attached in a chain. This arrangement is called:", choices: ["Strepto", "Staphylo", "Tetrad", "Sarcina"], answer: 0, explanation: "Diplo is a pair (1 plane); strepto is a chain (1 plane); tetrad is 2 planes; sarcina is 3 planes; staphylo is more than 3 planes." },
  { id: "ch4-036", chapter: "4", topic: "Cell morphology", question: "Which statement about cell morphology is true?", choices: ["It can narrow the possibilities but cannot on its own identify a species", "It identifies the exact species", "It can be determined without a microscope", "All species have a cell arrangement"], answer: 0, explanation: "Cell morphology means shape and arrangement. Some species have no arrangement." },
  { id: "ch4-037", chapter: "4", topic: "Cell envelope", question: "The cell envelope of Bacteria and Archaea always includes which layer?", choices: ["Cell membrane", "Cell wall", "Glycocalyx", "S layer"], answer: 0, explanation: "The CM is always present; the CW is common; glycocalyx or an S layer are sometimes added." },
  { id: "ch4-038", chapter: "4", topic: "Cell membrane", question: "Which of these is a function of the bacterial cell membrane?", choices: ["Selective permeability, maintaining chemical gradients, and ATP production in cell respiration", "Resisting osmotic lysis", "Storing the chromosome", "Protein synthesis"], answer: 0, explanation: "The CM is a barrier, anchors structures such as flagella, and is the site of ATP production in prokaryotes." },
  { id: "ch4-039", chapter: "4", topic: "Cell membrane", question: "Where is most ATP made during cell respiration in a prokaryotic cell?", choices: ["Cell membrane", "Mitochondria", "Nucleoid", "Ribosomes"], answer: 0, explanation: "Prokaryotes have no mitochondria; eukaryotes make most ATP in mitochondria." },
  { id: "ch4-040", chapter: "4", topic: "Cell membrane", question: "Why do very few antibiotics target the bacterial cell membrane?", choices: ["Animal cell membranes are structurally very similar, so the drugs would also harm our cells", "Bacteria have no cell membrane", "Cell membranes cannot be damaged", "Antibiotics cannot reach bacteria"], answer: 0, explanation: "Disinfectants and antiseptics such as alcohols and quats do harm the CM, but they are not given internally." },
  { id: "ch4-041", chapter: "4", topic: "Cell membrane", question: "Hopanoids in some bacterial membranes are best described as:", choices: ["A bacterial cholesterol-like molecule", "A type of peptidoglycan", "A toxin", "A ribosome subunit"], answer: 0, explanation: "Membranes contain phospholipids, proteins, and (in some) hopanoids or sterols." },
  { id: "ch4-042", chapter: "4", topic: "Cell membrane", question: "Which statement about phospholipid layers is correct?", choices: ["Most membranes are bilayers; some Archaea have monolayers", "All membranes are monolayers", "Bacteria use monolayers", "Eukaryotes use monolayers"], answer: 0, explanation: "Bilayers are typical; monolayers are rare and occur in some Archaea." },
  { id: "ch4-043", chapter: "4", topic: "Cell wall", question: "What is the main function of the bacterial cell wall?", choices: ["Protect against osmotic lysis and help maintain cell shape", "Produce ATP", "Make proteins", "Store DNA"], answer: 0, explanation: "The wall is a semi-rigid structure outside the cell membrane." },
  { id: "ch4-044", chapter: "4", topic: "Peptidoglycan", question: "Peptidoglycan (murein) is found in:", choices: ["Bacteria only", "Bacteria and animals", "Archaea and animals", "All cells"], answer: 0, explanation: "Animal cells lack peptidoglycan, which is why it is a good antibiotic target." },
  { id: "ch4-045", chapter: "4", topic: "Peptidoglycan", question: "Which two sugars alternate in a peptidoglycan strand?", choices: ["NAM and NAG", "Glucose and fructose", "Ribose and deoxyribose", "Lactose and sucrose"], answer: 0, explanation: "N-acetylmuramic acid and N-acetylglucosamine are joined by beta(1,4) bonds." },
  { id: "ch4-046", chapter: "4", topic: "Peptidoglycan", question: "Which enzyme (also called penicillin-binding protein) cross-links peptidoglycan?", choices: ["Transpeptidase", "Lysozyme", "ATP synthase", "Catalase"], answer: 0, explanation: "Growing bacteria use transpeptidase to form peptide cross-links." },
  { id: "ch4-047", chapter: "4", topic: "Peptidoglycan", question: "What happens when a beta-lactam antibiotic inhibits transpeptidase?", choices: ["New peptidoglycan cannot be cross-linked, so cells are vulnerable to osmotic lysis", "The cell grows faster", "The cell makes more peptidoglycan", "The cell forms an endospore"], answer: 0, explanation: "Without cross-links the wall cannot resist osmotic pressure in hypotonic environments." },
  { id: "ch4-048", chapter: "4", topic: "Peptidoglycan", question: "Two key links give peptidoglycan strength. They are:", choices: ["The beta(1,4) bond and the peptide cross-link", "Hydrogen bonds and ionic bonds", "Disulfide bonds and peptide bonds", "Phosphodiester bonds and glycosidic bonds"], answer: 0, explanation: "Glycan chains are joined by beta(1,4) bonds, and peptides link adjacent chains." },
  { id: "ch4-049", chapter: "4", topic: "Cell wall", question: "Which components does a Gram-positive cell wall have?", choices: ["Thick peptidoglycan with teichoic acids and lipoteichoic acids", "An outer membrane with LPS", "A thin peptidoglycan layer and thick periplasm", "Mycolic acids only"], answer: 0, explanation: "Gram-positive walls have no outer membrane and little or no periplasmic space." },
  { id: "ch4-050", chapter: "4", topic: "Cell wall", question: "Which components does a Gram-negative cell wall have?", choices: ["Thin peptidoglycan, an outer membrane with LPS, and a thick periplasmic space", "Thick peptidoglycan and teichoic acids", "No peptidoglycan", "Only mycolic acids"], answer: 0, explanation: "Gram-negative walls lack teichoic acids." },
  { id: "ch4-051", chapter: "4", topic: "Cell wall", question: "Compared with Gram-positive walls, Gram-negative walls are:", choices: ["Structurally weaker but chemically stronger", "Structurally stronger and chemically weaker", "Weaker in every way", "Identical"], answer: 0, explanation: "The outer membrane makes Gram-negatives harder to treat with many antibiotics and disinfectants." },
  { id: "ch4-052", chapter: "4", topic: "Lipid A", question: "When is Lipid A (endotoxin) released from Gram-negative bacteria?", choices: ["After cell death (lysis); it is not secreted", "Continuously by secretion", "Only by Gram-positives", "Only during sporulation"], answer: 0, explanation: "Release can be worse after antibiotic treatment because many cells lyse at once." },
  { id: "ch4-053", chapter: "4", topic: "Lipid A", question: "What can free endotoxin cause?", choices: ["A cytokine storm with fever, chills, clotting, and possibly endotoxic shock", "Flaccid paralysis", "Lockjaw", "Formation of endospores"], answer: 0, explanation: "Lipid A triggers a massive response from white blood cells." },
  { id: "ch4-054", chapter: "4", topic: "Cell wall", question: "Lysozyme in saliva and tears degrades peptidoglycan. Which cell type is more susceptible?", choices: ["Gram-positive", "Gram-negative", "Both equally", "Neither"], answer: 0, explanation: "In Gram-positives the peptidoglycan is exposed; Gram-negatives have an outer membrane covering it." },
  { id: "ch4-055", chapter: "4", topic: "Cell wall", question: "In general, which cell wall type is more resistant to antibiotics and chemical antiseptics and disinfectants?", choices: ["Gram-negative", "Gram-positive", "Neither", "Both equally"], answer: 0, explanation: "The outer membrane acts as an additional barrier." },
  { id: "ch4-056", chapter: "4", topic: "Cell wall", question: "Where is the peptidoglycan layer located in a Gram-negative cell wall?", choices: ["In the periplasmic space, between the cell membrane and the outer membrane", "Outside the outer membrane", "Inside the cytoplasm", "Outside the glycocalyx"], answer: 0, explanation: "The peptidoglycan sits in the periplasm." },
  { id: "ch4-057", chapter: "4", topic: "Mycoplasma", question: "Mycoplasma pneumoniae is naturally resistant to penicillins because it:", choices: ["Lacks a cell wall and so has no peptidoglycan or transpeptidase target", "Has a thick outer membrane", "Forms endospores", "Has a capsule"], answer: 0, explanation: "Beta-lactam drugs target transpeptidase, which acts on peptidoglycan." },
  { id: "ch4-058", chapter: "4", topic: "Mycobacterium", question: "Which statement describes the Mycobacterium cell wall?", choices: ["It is waxy with about 60% mycolic acids and is acid-fast positive", "It has no cell wall", "It is Gram-negative with LPS", "It has teichoic acids only"], answer: 0, explanation: "The waxy wall makes it hard to kill, slow growing, and stainable only with the acid-fast stain (carbol fuchsin)." },
  { id: "ch4-059", chapter: "4", topic: "Mycobacterium", question: "Which two diseases are caused by Mycobacterium species?", choices: ["Tuberculosis and leprosy", "Syphilis and Lyme disease", "Anthrax and tetanus", "Botulism and tetanus"], answer: 0, explanation: "M. tuberculosis causes TB and M. leprae causes leprosy." },
  { id: "ch4-060", chapter: "4", topic: "Cell wall", question: "Which statement about bacterial cell walls is TRUE?", choices: ["Not all bacteria have a cell wall (Mycoplasma lacks one)", "All Gram-negative bacteria are pathogens because they have LPS", "Gram-positive bacteria do not make peptidoglycan", "Gram-negative bacteria cannot be harmed by antibiotics"], answer: 0, explanation: "Several statements about walls are tempting but false; Mycoplasma shows that a wall is not universal." },
  { id: "ch4-061", chapter: "4", topic: "Motility", question: "How does a bacterial flagellum propel the cell?", choices: ["By rotary motion of a filament, like a propeller", "By whip-like waving of a membrane", "By pseudopods", "By cilia beating"], answer: 0, explanation: "Flagella rotate and are anchored in the cell membrane and wall." },
  { id: "ch4-062", chapter: "4", topic: "Motility", question: "Axial filaments (endoflagella) are found in which bacteria?", choices: ["Spirochetes", "Cocci", "Endospore-formers", "Mycoplasma"], answer: 0, explanation: "Axial filaments lie in the periplasm and rotate to propel the cell." },
  { id: "ch4-063", chapter: "4", topic: "Motility", question: "Treponema pallidum and Borrelia burgdorferi are spirochetes that cause which diseases?", choices: ["Syphilis and Lyme disease", "Anthrax and botulism", "Tuberculosis and leprosy", "Strep throat and acne"], answer: 0, explanation: "T. pallidum causes syphilis and B. burgdorferi causes Lyme disease." },
  { id: "ch4-064", chapter: "4", topic: "Attachment", question: "Why are biofilms medically important?", choices: ["They are involved in about 70% of infections, form on catheters, and resist antimicrobials", "They kill bacteria", "They are only found on plants", "They are always harmless"], answer: 0, explanation: "Biofilms are responsible for much nosocomial (hospital-acquired) disease." },
  { id: "ch4-065", chapter: "4", topic: "Attachment", question: "Fimbriae differ from sex pili in that fimbriae:", choices: ["Are shorter, more numerous, and used for attachment; sex pili are longer, 1-2 per cell, and used for conjugation", "Are used for conjugation", "Are made of flagellin", "Are longer than sex pili"], answer: 0, explanation: "Both are made of pilin." },
  { id: "ch4-066", chapter: "4", topic: "Attachment", question: "An S layer is:", choices: ["A single layer of protein produced during adverse conditions for protection and attachment", "A polysaccharide capsule", "A type of endospore coat", "A flagellum"], answer: 0, explanation: "The glycocalyx, by contrast, is made of repeating polysaccharide units." },
  { id: "ch4-067", chapter: "4", topic: "Glycocalyx", question: "Capsules are almost always polysaccharide-based. Which bacterium is an exception?", choices: ["Bacillus anthracis", "Streptococcus pneumoniae", "Escherichia coli", "Clostridium tetani"], answer: 0, explanation: "B. anthracis is the exception noted in lecture." },
  { id: "ch4-068", chapter: "4", topic: "Glycocalyx", question: "Capsule types are used to subtype Streptococcus pneumoniae. Roughly how many serotypes exist, and which vaccines use the capsule?", choices: ["About 90; Prevnar and Pneumovax", "About 3; Gardasil", "About 10; MMR", "About 200; Tdap"], answer: 0, explanation: "Capsule polysaccharide is a component of all pneumococcal vaccines." },
  { id: "ch4-069", chapter: "4", topic: "Cytoplasm", question: "Bacterial cytoplasm is about what percent water?", choices: ["80%", "20%", "50%", "100%"], answer: 0, explanation: "It also contains proteins, carbohydrates, lipids, and inorganic ions." },
  { id: "ch4-070", chapter: "4", topic: "Cytoplasm", question: "Which statement about the nucleoid and plasmids is correct?", choices: ["The nucleoid holds the circular chromosome with no membrane; plasmids are small, nonessential, independent circles of 5-100 genes", "The nucleoid is membrane-bound; plasmids are essential", "Plasmids are linear chromosomes", "The nucleoid contains ribosomes only"], answer: 0, explanation: "Plasmids can carry antibiotic resistance and are tools in biotechnology." },
  { id: "ch4-071", chapter: "4", topic: "Cytoplasm", question: "Are antibiotics that target the bacterial ribosome selectively toxic?", choices: ["Yes, because prokaryotic and eukaryotic ribosomes differ", "No, the ribosomes are identical", "Yes, because bacteria have no ribosomes", "No, because ribosomes are not essential"], answer: 0, explanation: "Bacterial (70S) ribosomes differ from eukaryotic (80S) ribosomes, so drugs can target one and not the other." },
  { id: "ch4-072", chapter: "4", topic: "Endospores", question: "Endospores are best described as:", choices: ["A dormant form of the same bacterium, not a means of reproduction", "A reproductive structure", "A type of capsule", "A virus"], answer: 0, explanation: "Vegetative cells and endospores are two forms of the same individual." },
  { id: "ch4-073", chapter: "4", topic: "Endospores", question: "In sporulation, what is the forespore?", choices: ["The smaller cell that develops into the endospore after being engulfed by the larger cell", "The larger mother cell", "The germinating cell", "The toxin"], answer: 0, explanation: "Engulfment gives the endospore its second membrane." },
  { id: "ch4-074", chapter: "4", topic: "Endospore-formers", question: "Match the pathogen to its toxin: Clostridium tetani produces:", choices: ["Tetanospasmin", "Anthrax toxin", "Toxin A and Toxin B", "Botulism toxin"], answer: 0, explanation: "C. difficile makes Toxins A and B; B. anthracis makes anthrax toxin; C. botulinum makes botulism toxin." },
  { id: "ch4-075", chapter: "4", topic: "Endospore-formers", question: "Clostridium difficile causes which disease and which toxins?", choices: ["Pseudomembranous colitis; Toxin A and Toxin B", "Tetanus; tetanospasmin", "Anthrax; anthrax toxin", "Botulism; botulism toxin"], answer: 0, explanation: "CDI is also called C. diff colitis." },
  { id: "ch4-076", chapter: "4", topic: "Botulism", question: "Clostridium botulinum is best described as a:", choices: ["Gram-positive, obligate anaerobic bacillus that forms endospores", "Gram-negative coccus", "Aerobic spirochete", "Facultative fungus"], answer: 0, explanation: "It lives as endospores in soil and sediments." },
  { id: "ch4-077", chapter: "4", topic: "Botulism", question: "Foodborne botulism is best described as:", choices: ["An intoxication: endospores survive improper canning, germinate, and preformed toxin is ingested", "An infection from honey", "An infection spread by sneezing", "A sexually transmitted infection"], answer: 0, explanation: "Infant botulism is the infection: endospores (for example in honey) germinate in the gut and release toxin." },
  { id: "ch4-078", chapter: "4", topic: "Botulism", question: "Botox is:", choices: ["A genetically modified botulism toxin", "A vaccine", "An antibiotic", "An endospore"], answer: 0, explanation: "Lecture noted that Botox is a modified form of botulism toxin." },
  { id: "ch4-079", chapter: "4", topic: "C. difficile", question: "What are the main risk factors for C. difficile infection?", choices: ["Age over 65, prior antimicrobial use, and large intestinal dysbiosis", "Eating undercooked meat", "Mosquito bites", "Swimming in lakes"], answer: 0, explanation: "C. diff is the leading cause of health-care-associated infectious diarrhea." },
  { id: "ch4-080", chapter: "4", topic: "C. difficile", question: "How does C. difficile spread and where does it grow?", choices: ["Endospores are ingested, germinate, and the vegetative cells colonize the large intestine", "It is inhaled and grows in the lungs", "It is passed by mosquitoes", "It grows on the skin"], answer: 0, explanation: "Endospores survive on surfaces and germinate only after reaching the anaerobic colon." },
  { id: "ch4-081", chapter: "4", topic: "C. difficile", question: "Which is the correct order of C. diff symptom severity?", choices: ["Watery diarrhea and colitis, pseudomembranous colitis, toxic megacolon", "Toxic megacolon, watery diarrhea, pseudomembranous colitis", "Pseudomembranous colitis, watery diarrhea, toxic megacolon", "Fever only"], answer: 0, explanation: "Toxins cause cell death and loss of cell-cell contact, leading to massive inflammation." },
  { id: "ch4-082", chapter: "4", topic: "C. difficile", question: "What is the paradox of treating C. difficile infection?", choices: ["Antibiotics are the most common therapy, yet they can cause recurrent infection by disrupting the microbiome", "There is no treatment", "Antibiotics make the endospores germinate", "The infection treats itself"], answer: 0, explanation: "Recurrent CDI (rCDI) after antibiotic therapy is common; FMT is an alternative." },
  { id: "ch4-083", chapter: "4", topic: "C. difficile", question: "A healthy gut microbiome is protective because it is:", choices: ["Diverse, and prevents C. difficile from taking over", "Sterile", "Made of one species", "Free of Gram-positives"], answer: 0, explanation: "Dysbiosis (lower diversity) from extensive antibiotic therapy lets C. diff take over." },
  { id: "ch4-084", chapter: "4", topic: "FMT", question: "In FMT, what is given to the patient?", choices: ["Screened stool from a healthy donor", "A purified toxin", "Antibiotics", "A vaccine"], answer: 0, explanation: "It restores a normal gut microbiome and can stop recurrent C. diff infection." },
  { id: "ch4-085", chapter: "4", topic: "FMT", question: "In the 2013 study, how did FMT compare with antibiotics for rCDI?", choices: ["About 95% cure with FMT versus about 31% with antibiotics", "About 31% with FMT versus 95% with antibiotics", "They were equal", "FMT was not tested"], answer: 0, explanation: "FMT is delivered by colonoscopy, tube, enema, or oral capsules." },
  { id: "ch4-086", chapter: "4", topic: "FMT", question: "FMT has historical roots in:", choices: ["4th-century China (\"yellow soup\")", "19th-century Germany", "The 2013 FDA approval", "Ancient Egypt"], answer: 0, explanation: "The practice is old; recurrent CDI cases increasing made it popular again." },
  { id: "ch4-087", chapter: "4", topic: "FMT", question: "Are the specific types of microbes in whole-stool FMT fully known?", choices: ["No, the donor stool contains a complex, not fully defined mix", "Yes, every species is known", "Yes, it is only one species", "It contains no bacteria"], answer: 0, explanation: "This unknown composition is part of the risk and motivates defined products." },
  { id: "ch4-088", chapter: "4", topic: "FMT", question: "SER-109 was FDA-approved in 2023. What is it?", choices: ["Oral capsules containing specific bacterial endospores", "A whole-stool enema", "An antibiotic", "A vaccine"], answer: 0, explanation: "Its composition is defined, unlike whole-stool FMT." },
  { id: "ch4-089", chapter: "4", topic: "FMT", question: "Which is a remaining question or risk of FMT?", choices: ["Unknown pathogens could be transferred, and how FMT works is not fully understood", "It always causes infection", "It has no unknowns", "It only works in children"], answer: 0, explanation: "The future direction is defined, lab-grown microbial consortia that are safer and more precise." },

  // ---------------- Chapter 5 — Eukaryotic Cells & Microorganisms ----------------
  { id: "ch5-001", chapter: "5", topic: "Eukaryotic structure", question: "Which polymer is the key component of fungal cell walls?", choices: ["Chitin", "Peptidoglycan", "Cellulose only", "Mycolic acid"], answer: 0, explanation: "Fungal walls contain chitin; algal walls typically contain cellulose." },
  { id: "ch5-002", chapter: "5", topic: "Eukaryotic structure", question: "Which feature of eukaryotic cell membranes differs from most bacterial membranes?", choices: ["Presence of sterols (such as cholesterol or ergosterol)", "Phospholipid bilayer", "Presence of proteins", "Selective permeability"], answer: 0, explanation: "Eukaryotic membranes contain sterols; most bacterial membranes do not." },
  { id: "ch5-003", chapter: "5", topic: "Eukaryotic structure", question: "Which organelle contains the cell's DNA in a eukaryote?", choices: ["Nucleus", "Golgi apparatus", "Lysosome", "Ribosome"], answer: 0, explanation: "The nucleus houses the chromosomes." },
  { id: "ch5-004", chapter: "5", topic: "Eukaryotic structure", question: "Which organelles contain digestive enzymes to break down materials?", choices: ["Lysosomes", "Mitochondria", "Chloroplasts", "Nucleus"], answer: 0, explanation: "Lysosomes contain hydrolytic enzymes for digestion." },
  { id: "ch5-005", chapter: "5", topic: "Eukaryotic structure", question: "What is the main function of mitochondria?", choices: ["ATP production via cellular respiration", "Photosynthesis", "Protein sorting", "DNA storage"], answer: 0, explanation: "Mitochondria are the sites of most ATP production in eukaryotes." },
  { id: "ch5-006", chapter: "5", topic: "Eukaryotic structure", question: "Which structure is found in BOTH prokaryotic and eukaryotic cells?", choices: ["Ribosomes", "Nucleus", "Golgi apparatus", "Mitochondria"], answer: 0, explanation: "All cells have ribosomes; the other structures are eukaryote-specific." },
  { id: "ch5-007", chapter: "5", topic: "Eukaryotic structure", question: "What is the correct order of structures involved in producing and secreting a protein?", choices: ["Ribosome on rough ER, transport vesicle, Golgi, secretory vesicle, cell membrane", "Golgi, ribosome, nucleus, lysosome", "Lysosome, Golgi, ER, membrane", "Nucleus, mitochondria, Golgi, ribosome"], answer: 0, explanation: "Proteins are made at the rough ER, sent in vesicles to the Golgi for modification, then secreted." },
  { id: "ch5-008", chapter: "5", topic: "Endosymbiosis", question: "According to the endosymbiotic theory, mitochondria evolved from:", choices: ["Aerobic bacteria (alpha-proteobacteria)", "Cyanobacteria", "Archaea", "Viruses"], answer: 0, explanation: "Mitochondria descended from engulfed aerobic bacteria." },
  { id: "ch5-009", chapter: "5", topic: "Endosymbiosis", question: "According to the endosymbiotic theory, chloroplasts evolved from:", choices: ["Cyanobacteria", "Alpha-proteobacteria", "Fungi", "Protozoa"], answer: 0, explanation: "Chloroplasts descended from engulfed photosynthetic cyanobacteria." },
  { id: "ch5-010", chapter: "5", topic: "Endosymbiosis", question: "Which is evidence supporting the endosymbiotic theory?", choices: ["Mitochondria and chloroplasts have their own circular DNA and 70S ribosomes", "They have a nucleus", "They lack membranes", "They contain 80S ribosomes only"], answer: 0, explanation: "Their bacteria-like DNA, ribosomes, and binary-fission-like division support bacterial origin." },
  { id: "ch5-011", chapter: "5", topic: "Ribosomes", question: "Cytoplasmic ribosomes of eukaryotes are ___, while those of bacteria are ___.", choices: ["80S; 70S", "70S; 80S", "60S; 40S", "50S; 30S"], answer: 0, explanation: "Eukaryotic cytoplasmic ribosomes are 80S (60S + 40S); bacterial are 70S (50S + 30S)." },
  { id: "ch5-012", chapter: "5", topic: "Eukaryotic microbes", question: "Which eukaryotic microbe group can be unicellular OR multicellular?", choices: ["Fungi", "Protozoa", "Bacteria", "Viruses"], answer: 0, explanation: "Fungi include unicellular yeasts and multicellular molds; protozoa are unicellular." },
  { id: "ch5-013", chapter: "5", topic: "Fungi", question: "How do most fungi obtain nutrients?", choices: ["They are heterotrophs that absorb nutrients from their surroundings", "Photosynthesis", "Chemosynthesis", "Ingestion by phagocytosis only"], answer: 0, explanation: "Fungi secrete enzymes and absorb the digested nutrients." },
  { id: "ch5-014", chapter: "5", topic: "Fungi", question: "Which term describes asexual yeast reproduction in which a small cell pinches off from the parent?", choices: ["Budding", "Binary fission", "Conjugation", "Sporulation"], answer: 0, explanation: "Yeasts commonly reproduce by budding." },
  { id: "ch5-015", chapter: "5", topic: "Fungi", question: "How do molds differ from yeasts?", choices: ["Molds are multicellular and form filaments (hyphae); yeasts are unicellular", "Molds are unicellular; yeasts are filamentous", "Molds are bacteria", "Yeasts form hyphae"], answer: 0, explanation: "Molds grow as hyphae and mycelium; yeasts are single cells." },
  { id: "ch5-016", chapter: "5", topic: "Fungi", question: "What does the term dimorphic fungus mean?", choices: ["It grows as a yeast at body temperature and as a mold at room temperature", "It has two nuclei", "It reproduces only sexually", "It is both a virus and a fungus"], answer: 0, explanation: "Dimorphic fungi switch forms with temperature, which is relevant to many pathogens." },
  { id: "ch5-017", chapter: "5", topic: "Fungi", question: "Cutaneous mycoses typically infect which area?", choices: ["Skin, hair, and nails", "Lungs and deep organs", "Blood only", "Nervous system only"], answer: 0, explanation: "Cutaneous mycoses (for example tineas) are superficial; systemic mycoses spread to deep organs." },
  { id: "ch5-018", chapter: "5", topic: "Fungi", question: "Coccidioidomycosis (Valley fever) is classified as which type of mycosis?", choices: ["Systemic", "Cutaneous", "Superficial", "Not a fungal disease"], answer: 0, explanation: "It is usually acquired by inhaling spores and can spread systemically." },
  { id: "ch5-019", chapter: "5", topic: "Fungi", question: "Tinea infections such as ringworm and athlete's foot are caused by:", choices: ["Dermatophyte fungi", "Protozoa", "Helminths", "Bacteria"], answer: 0, explanation: "Tineas are cutaneous fungal infections caused by dermatophytes." },
  { id: "ch5-020", chapter: "5", topic: "Protozoa", question: "Which protozoan group moves using pseudopods?", choices: ["Amoebas", "Flagellates", "Apicomplexa", "Ciliates"], answer: 0, explanation: "Amoebas move by extending pseudopods." },
  { id: "ch5-021", chapter: "5", topic: "Protozoa", question: "Which protozoan group is generally nonmotile as adults and includes parasites such as Plasmodium?", choices: ["Apicomplexa (sporozoans)", "Amoebas", "Flagellates", "Ciliates"], answer: 0, explanation: "Apicomplexans are nonmotile parasites with a complex life cycle." },
  { id: "ch5-022", chapter: "5", topic: "Protozoa", question: "How does a trophozoite differ from a cyst?", choices: ["A trophozoite is the active, feeding form; a cyst is a dormant, resistant form", "A trophozoite is dormant; a cyst is active", "They are the same", "A cyst is the feeding form"], answer: 0, explanation: "Trophozoites feed and multiply; cysts survive harsh conditions." },
  { id: "ch5-023", chapter: "5", topic: "Protozoa", question: "Why is a cyst stage useful for some protozoans?", choices: ["It allows survival outside the host and transmission", "It increases motility", "It makes them photosynthetic", "It speeds reproduction"], answer: 0, explanation: "Cysts resist drying, chemicals, and other stresses, helping transmission." },
  { id: "ch5-024", chapter: "5", topic: "Protozoa", question: "Giardia is a:", choices: ["Flagellated protozoan causing diarrhea, spread via cysts in contaminated water", "Helminth", "Mosquito-borne apicomplexan", "Mold"], answer: 0, explanation: "Giardia causes giardiasis, commonly acquired from contaminated water." },
  { id: "ch5-025", chapter: "5", topic: "Protozoa", question: "Trichomonas vaginalis is best described as:", choices: ["A flagellated protozoan that causes a sexually transmitted infection", "An amoeba that causes dysentery", "A helminth", "A fungus"], answer: 0, explanation: "T. vaginalis is a flagellate transmitted sexually; it has no cyst stage." },
  { id: "ch5-026", chapter: "5", topic: "Protozoa", question: "Entamoeba histolytica causes:", choices: ["Amoebic dysentery", "Malaria", "Strep throat", "Ringworm"], answer: 0, explanation: "E. histolytica is an amoeba spread by fecal-oral transmission of cysts." },
  { id: "ch5-027", chapter: "5", topic: "Protozoa", question: "Plasmodium, the cause of malaria, is transmitted to humans by:", choices: ["Anopheles mosquitoes", "Contaminated water cysts", "Sexual contact", "Undercooked pork"], answer: 0, explanation: "Plasmodium is an apicomplexan spread by female Anopheles mosquitoes." },
  { id: "ch5-028", chapter: "5", topic: "Helminths", question: "Which are the three major groups of parasitic helminths?", choices: ["Tapeworms, flukes, and roundworms", "Amoebas, ciliates, and flagellates", "Yeasts, molds, and mushrooms", "Cocci, bacilli, and spirilla"], answer: 0, explanation: "Helminths are flatworms (tapeworms and flukes) and roundworms." },
  { id: "ch5-029", chapter: "5", topic: "Helminths", question: "What is the most important trait used to identify a helminth in a stool sample?", choices: ["The shape and features of its eggs", "Its color", "Its Gram reaction", "Its flagella"], answer: 0, explanation: "Helminth eggs in stool are used for diagnosis." },
  { id: "ch5-030", chapter: "5", topic: "Helminths", question: "A definitive host is the host that harbors the parasite's:", choices: ["Adult, sexually mature stage", "Larval stage only", "Eggs only", "Cyst stage only"], answer: 0, explanation: "The intermediate host harbors larval or immature stages." },
  { id: "ch5-031", chapter: "5", topic: "Helminths", question: "Which body system do helminths most commonly infect in humans?", choices: ["Digestive (intestinal) system", "Respiratory system", "Nervous system", "Skin only"], answer: 0, explanation: "Many helminths live in the intestines." },
  { id: "ch5-032", chapter: "5", topic: "Helminths", question: "Which statement about pinworms is correct?", choices: ["They are roundworms spread by the fecal-oral route and cause anal itching", "They are tapeworms with proglottids", "They require an intermediate host", "They are spread by mosquitoes"], answer: 0, explanation: "Pinworm (Enterobius) eggs are swallowed; females lay eggs near the anus." },
  { id: "ch5-033", chapter: "5", topic: "Helminths", question: "Tapeworms are typically acquired by:", choices: ["Eating undercooked meat containing larval cysts", "Mosquito bites", "Sexual contact", "Inhaling spores"], answer: 0, explanation: "Tapeworms have intermediate hosts such as cattle and pigs; segments called proglottids make up the body." },

  // ---------------- Chapter 5 — From lecture slides (Ch 5 PowerPoint) ----------------
  { id: "ch5-034", chapter: "5", topic: "Eukaryotic structure", question: "Which statement about cilia is correct?", choices: ["Cilia are numerous, short, hair-like structures found in eukaryotes but not prokaryotes", "Prokaryotes have cilia made of tubulin", "Cilia are long and few", "Cilia are found only in bacteria"], answer: 0, explanation: "Flagella are few, long, and whip-like; prokaryotes have flagella (made of different proteins) but no cilia." },
  { id: "ch5-035", chapter: "5", topic: "Eukaryotic structure", question: "Eukaryotic flagella and cilia have which internal arrangement?", choices: ["9+2 microtubules made of tubulin, covered by the cell membrane", "A rotating filament of flagellin", "A single microtubule", "Peptidoglycan fibers"], answer: 0, explanation: "They are about 10 times thicker than prokaryotic flagella." },
  { id: "ch5-036", chapter: "5", topic: "Eukaryotic structure", question: "The eukaryotic glycocalyx (extracellular matrix) functions in:", choices: ["Adherence, protection, and signal reception", "Protein synthesis", "ATP production", "DNA storage"], answer: 0, explanation: "It is made of polysaccharides, as a network of fibers, slime layer, or capsule." },
  { id: "ch5-037", chapter: "5", topic: "Eukaryotic structure", question: "True or false: animal cells have cell walls.", choices: ["False", "True", "True, made of chitin", "True, made of cellulose"], answer: 0, explanation: "Animal cells and protozoans have no cell wall; protozoans have a pellicle outside the plasma membrane." },
  { id: "ch5-038", chapter: "5", topic: "Eukaryotic structure", question: "Match the group to its cell wall component.", choices: ["Fungi: chitin and glucans; plants and algae: cellulose", "Fungi: cellulose; plants: chitin", "Fungi: peptidoglycan; algae: chitin", "Fungi and plants: peptidoglycan"], answer: 0, explanation: "Only plants, algae, and fungi have cell walls among eukaryotes; these protect against osmotic lysis." },
  { id: "ch5-039", chapter: "5", topic: "Eukaryotic structure", question: "The eukaryotic plasma membrane is similar to the bacterial one except for the presence of:", choices: ["Sterols", "Phospholipids", "Proteins", "A bilayer"], answer: 0, explanation: "Sterols such as cholesterol and ergosterol give eukaryotic membranes added stability." },
  { id: "ch5-040", chapter: "5", topic: "Eukaryotic structure", question: "True or false: ribosomes are organelles.", choices: ["False; organelles are membrane-bound and ribosomes are not", "True", "True, but only in eukaryotes", "True, but only in prokaryotes"], answer: 0, explanation: "Organelles are membrane-bound structures with specialized functions." },
  { id: "ch5-041", chapter: "5", topic: "Ribosomes", question: "Eukaryotic ribosomes are composed of what, and where are they found?", choices: ["rRNA and proteins; scattered in the cytoplasm and attached to the rough ER", "DNA and lipids; only in the nucleus", "Only proteins; only in mitochondria", "rRNA only; only on the Golgi"], answer: 0, explanation: "They are 80S, larger than prokaryotic 70S ribosomes, and make proteins (translation)." },
  { id: "ch5-042", chapter: "5", topic: "Eukaryotic structure", question: "The cytoskeleton functions in:", choices: ["Cell shape and support, anchoring organelles, and moving vesicles", "Making ATP", "Digesting food", "Photosynthesis"], answer: 0, explanation: "It also enables the cell to change shape and move." },
  { id: "ch5-043", chapter: "5", topic: "Eukaryotic structure", question: "Which structures are part of the endomembrane system?", choices: ["Nucleus, endoplasmic reticulum, Golgi complex, and membrane vesicles", "Mitochondria and chloroplasts", "Ribosomes and flagella", "Cell wall and glycocalyx"], answer: 0, explanation: "Mitochondria and chloroplasts are organelles but are not part of the endomembrane system." },
  { id: "ch5-044", chapter: "5", topic: "Eukaryotic structure", question: "Nuclear pores are found in which structure?", choices: ["The nuclear envelope", "The Golgi", "The plasma membrane", "The mitochondrial matrix"], answer: 0, explanation: "Pores let materials pass between the nucleus and cytoplasm." },
  { id: "ch5-045", chapter: "5", topic: "Eukaryotic structure", question: "Which is the main role of smooth ER versus rough ER?", choices: ["Smooth ER makes phospholipids, fats, and steroids; rough ER makes proteins (membrane and secreted proteins)", "Smooth ER makes proteins; rough ER makes lipids", "Both make only ATP", "Neither is involved in synthesis"], answer: 0, explanation: "Rough ER is studded with ribosomes." },
  { id: "ch5-046", chapter: "5", topic: "Eukaryotic structure", question: "What is the function of the Golgi complex?", choices: ["It sorts and modifies lipids and proteins from the ER and forms lysosomes and vacuoles", "It makes ATP", "It stores DNA", "It performs photosynthesis"], answer: 0, explanation: "Secretory and membrane proteins leave the Golgi in vesicles." },
  { id: "ch5-047", chapter: "5", topic: "Eukaryotic structure", question: "Membrane vesicles:", choices: ["Are small membrane spheres that move materials and can fuse with or pinch off from organelles or the cell membrane", "Are always permanent", "Store the chromosomes", "Make ATP"], answer: 0, explanation: "Types include transport vesicles, secretory vesicles, lysosomes, and peroxisomes." },
  { id: "ch5-048", chapter: "5", topic: "Eukaryotic structure", question: "Which sequence correctly traces a secreted protein?", choices: ["Nucleus, rough ER, Golgi, vesicles, secretion (exocytosis)", "Golgi, nucleus, ER, secretion", "Rough ER, nucleus, lysosome, secretion", "Mitochondria, Golgi, nucleus, secretion"], answer: 0, explanation: "The DNA is in the nucleus, ribosomes on rough ER make the protein, the Golgi modifies it, and vesicles carry it out." },
  { id: "ch5-049", chapter: "5", topic: "Eukaryotic structure", question: "Which structure produces ATP during photosynthesis in eukaryotes?", choices: ["Chloroplasts", "Mitochondria", "Golgi", "Lysosomes"], answer: 0, explanation: "Some bacteria (cyanobacteria) photosynthesize without chloroplasts." },
  { id: "ch5-050", chapter: "5", topic: "Endosymbiosis", question: "Which features are shared by mitochondria and chloroplasts?", choices: ["Double membrane, binary fission, their own circular DNA, and 70S ribosomes", "A single membrane and linear DNA", "80S ribosomes and a nucleus", "No DNA"], answer: 0, explanation: "These traits support their evolution from bacterial ancestors." },
  { id: "ch5-051", chapter: "5", topic: "Endosymbiosis", question: "Which is evidence for the endosymbiotic theory?", choices: ["Organelles are inhibited by antibiotics and have an ETC and ATP synthase like bacteria", "Organelles have a nucleus", "Organelles have 80S ribosomes", "Organelles lack DNA"], answer: 0, explanation: "Other evidence includes size and shape, circular DNA with bacterial sequences, binary fission, and 70S ribosomes." },
  { id: "ch5-052", chapter: "5", topic: "Endosymbiosis", question: "Roughly when did mitochondria and chloroplasts evolve from bacterial ancestors?", choices: ["Mitochondria about 3 billion years ago; chloroplasts about 2.5 billion years ago", "Both about 100 years ago", "Mitochondria 1 million years ago", "Chloroplasts before mitochondria by 5 billion years"], answer: 0, explanation: "Chloroplasts evolved from a cyanobacterial ancestor." },
  { id: "ch5-053", chapter: "5", topic: "Endosymbiosis", question: "What is the likely origin of the two mitochondrial membranes?", choices: ["The inner is the bacterial cell membrane; the outer comes from the host cell that engulfed it", "Both came from the nucleus", "Both came from the Golgi", "They were made by lysosomes"], answer: 0, explanation: "A host cell engulfed an aerobically respiring bacterium." },
  { id: "ch5-054", chapter: "5", topic: "Endosymbiosis", question: "Buchnera living inside aphid cells is an example of:", choices: ["An intracellular endosymbiotic bacterium", "A virus", "A mitochondrion", "A fungus"], answer: 0, explanation: "Many eukaryotes have intracellular endosymbiotic bacteria." },
  { id: "ch5-055", chapter: "5", topic: "Fungi", question: "Fungi are best described by which nutritional type and feeding method?", choices: ["Chemoorganoheterotrophs that absorb organic molecules", "Photoautotrophs", "Chemoautotrophs that ingest food", "Phototrophs that absorb light"], answer: 0, explanation: "Mycology is the study of fungi." },
  { id: "ch5-056", chapter: "5", topic: "Fungi", question: "All fungi are multicellular EXCEPT:", choices: ["Yeasts", "Molds", "Mushrooms", "Puffballs"], answer: 0, explanation: "Fungi form unicellular yeasts, filamentous molds, and fleshy fungi." },
  { id: "ch5-057", chapter: "5", topic: "Fungi", question: "Roughly how many fungal species are pathogenic?", choices: ["About 300 of over 100,000", "Most of them", "About half", "None"], answer: 0, explanation: "Fungi also recycle elements, decompose plants, and are used in food and drug production." },
  { id: "ch5-058", chapter: "5", topic: "Fungi", question: "Why are fungal infections harder to treat than bacterial infections?", choices: ["Fungal cells are more similar to our cells than bacterial cells are", "Fungi are always anaerobic", "Fungi are resistant to all antibiotics by conjugation", "Fungal infections are easy to treat"], answer: 0, explanation: "Drugs that harm fungi tend to harm human cells too, so treatments are often toxic." },
  { id: "ch5-059", chapter: "5", topic: "Fungi", question: "Why are fleshy fungi such as puffballs and toadstools not studied as microbes?", choices: ["They are multicellular, solid masses of hyphae", "They are bacteria", "They are viruses", "They are single-celled"], answer: 0, explanation: "The focus is on molds and yeasts." },
  { id: "ch5-060", chapter: "5", topic: "Fungi", question: "In molds, what are vegetative hyphae and aerial hyphae?", choices: ["Vegetative hyphae form the mycelium; aerial hyphae form reproductive structures such as spores", "Vegetative hyphae form spores; aerial hyphae form mycelium", "Both only absorb water", "Both are nuclei"], answer: 0, explanation: "Molds are multicellular with hyphae and grow by elongation and fragmentation." },
  { id: "ch5-061", chapter: "5", topic: "Fungi", question: "How do septate hyphae differ from nonseptate hyphae?", choices: ["Septate hyphae have cross-walls dividing the cells", "Septate hyphae are single-celled", "Septate hyphae have no cell wall", "Nonseptate hyphae are divided"], answer: 0, explanation: "Nonseptate hyphae are continuous tubes with many nuclei." },
  { id: "ch5-062", chapter: "5", topic: "Fungi", question: "Which statement about fungal spores is correct?", choices: ["They are reproductive, less stress-resistant than bacterial endospores, and used to identify fungi", "They are dormant survival forms identical to endospores", "They are only sexual", "They are always highly heat resistant"], answer: 0, explanation: "Asexual spores are most common and enable fungi to spread; Aspergillus and Rhizopus are examples." },
  { id: "ch5-063", chapter: "5", topic: "Fungi", question: "Which condition describes yeasts as facultative anaerobes?", choices: ["With O2 they respire aerobically; without O2 they ferment", "They need O2 always", "They never use O2", "They photosynthesize"], answer: 0, explanation: "Yeasts grow faster aerobically because aerobic respiration yields more ATP." },
  { id: "ch5-064", chapter: "5", topic: "Fungi", question: "How can yeasts reproduce?", choices: ["By budding (leaving bud scars), binary fission, or sexual fusion", "Only by endospores", "Only by hyphae", "Only by viruses"], answer: 0, explanation: "Yeasts sometimes form pseudohyphae." },
  { id: "ch5-065", chapter: "5", topic: "Fungi", question: "How can you tell yeast from bacteria under the microscope?", choices: ["Yeast cells are larger and eukaryotic with a nucleus and often bud scars", "Yeast are smaller than bacteria", "Bacteria have a nucleus", "They cannot be distinguished"], answer: 0, explanation: "Both are unicellular, but yeasts are eukaryotes." },
  { id: "ch5-066", chapter: "5", topic: "Fungi", question: "Dimorphic fungi grow as which forms at which temperatures?", choices: ["Mold at 25 C; yeast at 37 C", "Yeast at 25 C; mold at 37 C", "Mold at 37 C and yeast at 100 C", "Only mold at all temperatures"], answer: 0, explanation: "They can cause serious systemic infections in animals." },
  { id: "ch5-067", chapter: "5", topic: "Fungi", question: "Which description fits mycoses (fungal diseases)?", choices: ["Generally chronic and slow-growing, with difficult treatment", "Always acute and fast", "Easy to treat with specific drugs", "Always contagious"], answer: 0, explanation: "The four classes are systemic, subcutaneous, cutaneous, and superficial." },
  { id: "ch5-068", chapter: "5", topic: "Fungi", question: "Athlete's foot, jock itch, and scalp or body ringworm are:", choices: ["Different types of ringworm (tineas) caused by dermatophytes", "Caused by worms", "Systemic mycoses", "Bacterial infections"], answer: 0, explanation: "Ringworm is not a worm; the infection is fungal." },
  { id: "ch5-069", chapter: "5", topic: "Fungi", question: "Dermatophytes infect keratin-containing tissue by secreting:", choices: ["Keratinase", "Lysozyme", "Transpeptidase", "Hemolysin"], answer: 0, explanation: "They infect non-living epidermis, hair, and nails; spread is by contact or fomites; treatment is topical or oral antifungals." },
  { id: "ch5-070", chapter: "5", topic: "Fungi", question: "Which describes systemic mycoses?", choices: ["Deep infections of internal organs, usually from inhaled spores of dimorphic soil fungi, and not communicable", "Infections of only the skin", "Spread person to person by touch", "Always mild"], answer: 0, explanation: "The respiratory tract is generally the primary site; they can be asymptomatic or life-threatening." },
  { id: "ch5-071", chapter: "5", topic: "Fungi", question: "Coccidioidomycosis is caused by Coccidioides immitis. Which statement is correct?", choices: ["It lives in desert soils of the American Southwest, is acquired by inhaling spores, and is treated with fluconazole", "It is spread by mosquitoes", "It lives in freshwater", "It is treated with metronidazole"], answer: 0, explanation: "Diagnosis includes spherules in sputum or spinal fluid; prevention includes wearing a mask when working with soil." },
  { id: "ch5-072", chapter: "5", topic: "Protozoa", question: "Which describes protozoa?", choices: ["Unicellular eukaryotes, mostly chemoorganoheterotrophs, with various forms of motility and some forming cysts", "Multicellular animals", "Prokaryotes with cell walls", "Photosynthetic only"], answer: 0, explanation: "Some are nonmotile (Apicomplexa)." },
  { id: "ch5-073", chapter: "5", topic: "Protozoa", question: "How do excystment and encystment differ?", choices: ["Excystment forms the active trophozoite; encystment forms the dormant cyst", "Excystment forms the cyst", "They are the same", "Both form spores"], answer: 0, explanation: "The trophozoite is the metabolically active, motile, feeding stage." },
  { id: "ch5-074", chapter: "5", topic: "Protozoa", question: "Protozoa with flagella often:", choices: ["Lack mitochondria, live as symbionts in animal digestive tracts, and form cysts", "Have chloroplasts", "Move by pseudopods only", "Are nonmotile"], answer: 0, explanation: "Human pathogens include Giardia and Trichomonas." },
  { id: "ch5-075", chapter: "5", topic: "Protozoa", question: "Giardia lamblia causes giardiasis, also called:", choices: ["Hiker's diarrhea", "Valley fever", "Ringworm", "Strep throat"], answer: 0, explanation: "It is the most common cause of waterborne diarrhea in the US and is spread by infective cysts; it lacks mitochondria." },
  { id: "ch5-076", chapter: "5", topic: "Protozoa", question: "Which is true of Trichomonas vaginalis?", choices: ["It is the most common non-viral STI in the US, has no cyst stage, and is treated with metronidazole", "It forms cysts", "It is spread by water", "It has mitochondria"], answer: 0, explanation: "It is anaerobic with an undulating membrane and flagellum; males are often asymptomatic." },
  { id: "ch5-077", chapter: "5", topic: "Protozoa", question: "Amoebas move and feed using:", choices: ["Pseudopodia", "Cilia", "Flagella", "Axial filaments"], answer: 0, explanation: "They reproduce by fission." },
  { id: "ch5-078", chapter: "5", topic: "Protozoa", question: "Entamoeba histolytica causes amebiasis, which features:", choices: ["Amebic dysentery with blood and mucus in stool, possible spread to liver, lungs, and brain", "Malaria-like fever cycles", "Skin ringworm", "Strep throat"], answer: 0, explanation: "It is passed by ingesting cysts and treated with metronidazole." },
  { id: "ch5-079", chapter: "5", topic: "Protozoa", question: "Apicomplexans (sporozoa) are characterized by:", choices: ["Obligate intracellular parasitism, apical organelles that penetrate host cells, and a complex life cycle", "Pseudopods", "Free-living photosynthesis", "Cilia"], answer: 0, explanation: "Mature forms are nonmotile and have sexual and asexual stages (schizogony)." },
  { id: "ch5-080", chapter: "5", topic: "Protozoa", question: "In the Plasmodium life cycle, which is the definitive host and which is the intermediate host?", choices: ["Mosquito is definitive; human is intermediate", "Human is definitive; mosquito is intermediate", "Both are definitive", "Neither"], answer: 0, explanation: "Sexual reproduction occurs in the mosquito; asexual in the human." },
  { id: "ch5-081", chapter: "5", topic: "Protozoa", question: "Which form of Plasmodium is the infective stage for humans?", choices: ["Sporozoites", "Merozoites", "Gametocytes", "Cysts"], answer: 0, explanation: "Sporozoites are found in mosquito salivary glands." },
  { id: "ch5-082", chapter: "5", topic: "Protozoa", question: "When Plasmodium first infects a human, where does it go?", choices: ["Liver cells", "Red blood cells", "Nerve cells", "White blood cells"], answer: 0, explanation: "Sporozoites enter liver cells first." },
  { id: "ch5-083", chapter: "5", topic: "Protozoa", question: "In a liver cell, the sporozoite DNA is copied repeatedly to form a multinucleated cell called a:", choices: ["Schizont", "Gamete", "Cyst", "Spore"], answer: 0, explanation: "The schizont divides into many merozoites by schizogony." },
  { id: "ch5-084", chapter: "5", topic: "Protozoa", question: "When an infected liver cell ruptures, merozoites enter the blood and infect:", choices: ["Red blood cells", "White blood cells", "Neurons", "Skin cells"], answer: 0, explanation: "They form a ring stage and produce more merozoites and gametocytes." },
  { id: "ch5-085", chapter: "5", topic: "Protozoa", question: "What causes the fever and chills of malaria?", choices: ["Waste products released as merozoites reproduce in and burst red blood cells", "Endotoxin from Gram-negative bacteria", "Fungal toxins", "Antibodies"], answer: 0, explanation: "The cycle repeats as merozoites reinfect red cells." },
  { id: "ch5-086", chapter: "5", topic: "Protozoa", question: "Which Plasmodium form is picked up by a mosquito during a blood meal?", choices: ["Gametocytes", "Sporozoites", "Cysts", "Schizonts"], answer: 0, explanation: "Gametocytes mate in the mosquito and produce sporozoites." },
  { id: "ch5-087", chapter: "5", topic: "Protozoa", question: "Plasmodium reproduces ___ in the human and ___ in the mosquito.", choices: ["Asexually; sexually", "Sexually; asexually", "Only asexually", "Only sexually"], answer: 0, explanation: "Malaria is caused by four Plasmodium species and spread by female Anopheles mosquitoes." },
  { id: "ch5-088", chapter: "5", topic: "Helminths", question: "Which describes parasitic helminths?", choices: ["Animals that are multicellular as adults; adults are nonmotile and identified by shape, size, hooks, suckers, and eggs", "Unicellular eukaryotes", "Prokaryotes", "Fungi"], answer: 0, explanation: "Eggs and larvae are unicellular; gametes may have flagella." },
  { id: "ch5-089", chapter: "5", topic: "Helminths", question: "Tapeworms (cestodes) are:", choices: ["Flattened, segmented worms with no digestive tract, all hermaphroditic", "Round with a complete digestive tract", "Flat and nonsegmented with sucking mouthparts", "Unicellular"], answer: 0, explanation: "Flukes (trematodes) are flattened and nonsegmented with sucking mouthparts." },
  { id: "ch5-090", chapter: "5", topic: "Helminths", question: "Roundworms (nematodes) are characterized by:", choices: ["A complete digestive tract and protective cuticle", "No digestive tract", "Segmented flat bodies", "Sucking mouthparts only"], answer: 0, explanation: "Pinworms are an example, and they mature within one host." },
  { id: "ch5-091", chapter: "5", topic: "Helminths", question: "Pinworm disease (enterobiasis) is caused by:", choices: ["Enterobius vermicularis", "Taenia", "Giardia", "Plasmodium"], answer: 0, explanation: "Pinworms are roundworms that complete their life cycle in a single host." },

  // ---------------- Chapter 10 — Microbial Metabolism ----------------
  { id: "ch10-001", chapter: "10", topic: "Metabolism basics", question: "Which statement distinguishes anabolism from catabolism?", choices: ["Anabolism builds complex molecules and requires energy; catabolism breaks them down and releases energy", "Anabolism breaks down molecules; catabolism builds them", "Both release energy", "Neither involves enzymes"], answer: 0, explanation: "Anabolism is biosynthesis; catabolism is degradation." },
  { id: "ch10-002", chapter: "10", topic: "Metabolism basics", question: "Which is an example of a catabolic process?", choices: ["Glycolysis", "Protein synthesis", "DNA replication", "Photosynthetic sugar building"], answer: 0, explanation: "Glycolysis breaks glucose down." },
  { id: "ch10-003", chapter: "10", topic: "ATP", question: "ATP is a modified nucleotide containing which parts?", choices: ["Adenine, ribose, and three phosphate groups", "Thymine, deoxyribose, and one phosphate", "Cytosine, ribose, and two phosphates", "Glucose and phosphate"], answer: 0, explanation: "ATP is an RNA nucleotide with three phosphates." },
  { id: "ch10-004", chapter: "10", topic: "ATP", question: "What happens during ATP hydrolysis?", choices: ["The terminal phosphate is removed, forming ADP and releasing energy", "ADP gains a phosphate and absorbs energy", "ATP is made", "DNA is replicated"], answer: 0, explanation: "Breaking the high-energy phosphate bond releases usable energy; making ATP requires energy." },
  { id: "ch10-005", chapter: "10", topic: "Enzymes", question: "What are enzymes?", choices: ["Biological catalysts, usually proteins, that lower activation energy", "Lipids that store energy", "Nucleic acids that store genetic information", "Sugars that provide energy"], answer: 0, explanation: "Enzymes speed up reactions without being consumed." },
  { id: "ch10-006", chapter: "10", topic: "Enzymes", question: "Denaturation of a protein means:", choices: ["Loss of its three-dimensional shape and function", "Increase in its activity", "Formation of new peptide bonds", "Conversion into a lipid"], answer: 0, explanation: "Heat, extreme pH, and some chemicals denature proteins." },
  { id: "ch10-007", chapter: "10", topic: "Enzymes", question: "A conjugated enzyme differs from a non-conjugated enzyme because it:", choices: ["Contains a protein plus a nonprotein cofactor", "Is made only of protein", "Has no active site", "Is not affected by pH"], answer: 0, explanation: "Conjugated enzymes need a cofactor to be active." },
  { id: "ch10-008", chapter: "10", topic: "Enzymes", question: "Which pair correctly names the two types of cofactors?", choices: ["Ions and coenzymes", "Proteins and lipids", "Substrates and products", "DNA and RNA"], answer: 0, explanation: "Cofactors are metal ions (for example Mg2+) or organic coenzymes (for example NAD+)." },
  { id: "ch10-009", chapter: "10", topic: "Enzymes", question: "Which of these is a coenzyme?", choices: ["NAD+", "Mg2+", "Glucose", "ATP synthase"], answer: 0, explanation: "NAD+, FAD, and coenzyme A are coenzymes." },
  { id: "ch10-010", chapter: "10", topic: "Enzymes", question: "How does a competitive inhibitor work?", choices: ["It binds to the active site, blocking the substrate", "It binds elsewhere and changes the enzyme's shape", "It denatures the substrate", "It increases enzyme speed"], answer: 0, explanation: "An allosteric (non-competitive) inhibitor binds outside the active site." },
  { id: "ch10-011", chapter: "10", topic: "Enzymes", question: "How does an allosteric (non-competitive) inhibitor work?", choices: ["It binds a site other than the active site and changes the enzyme's shape", "It binds the active site", "It acts as a substrate", "It is used up in the reaction"], answer: 0, explanation: "The shape change reduces the enzyme's activity." },
  { id: "ch10-012", chapter: "10", topic: "Enzymes", question: "As substrate concentration increases, enzyme activity:", choices: ["Increases until the enzymes are saturated, then levels off", "Always decreases", "Increases forever", "Stays the same"], answer: 0, explanation: "When all active sites are occupied, activity plateaus." },
  { id: "ch10-013", chapter: "10", topic: "Enzymes", question: "As temperature rises well above the optimum, enzyme activity:", choices: ["Drops sharply because the enzyme denatures", "Keeps increasing", "Stays constant", "Becomes competitive"], answer: 0, explanation: "Activity rises to an optimum, then falls as the protein denatures." },
  { id: "ch10-014", chapter: "10", topic: "Redox", question: "What does it mean that oxidation and reduction reactions are coupled?", choices: ["Whenever one substance is oxidized, another is reduced", "Oxidation occurs without reduction", "They occur in different cells", "They require no electrons"], answer: 0, explanation: "Electrons lost by one molecule are gained by another." },
  { id: "ch10-015", chapter: "10", topic: "Redox", question: "Reduction is:", choices: ["Gain of electrons", "Loss of electrons", "Loss of protons only", "Hydrolysis of ATP"], answer: 0, explanation: "Oxidation is loss of electrons; reduction is gain." },
  { id: "ch10-016", chapter: "10", topic: "Redox", question: "Which are the reduced forms of electron-carrier coenzymes?", choices: ["NADH and FADH2", "NAD+ and FAD", "ATP and ADP", "CO2 and O2"], answer: 0, explanation: "NADH and FADH2 carry electrons to the electron transport chain." },
  { id: "ch10-017", chapter: "10", topic: "Respiration vs fermentation", question: "Rank ATP yield per glucose from greatest to least.", choices: ["Aerobic respiration, anaerobic respiration, fermentation", "Fermentation, anaerobic respiration, aerobic respiration", "Anaerobic respiration, aerobic respiration, fermentation", "All yield the same"], answer: 0, explanation: "Aerobic respiration yields the most, fermentation the least (about 2 ATP)." },
  { id: "ch10-018", chapter: "10", topic: "Respiration vs fermentation", question: "A hydrogen ion (H+) is best described as:", choices: ["A hydrogen atom that lost its electron, essentially a proton", "A neutral hydrogen atom", "A hydroxide ion", "A water molecule"], answer: 0, explanation: "H is neutral with one proton and one electron; H+ lacks the electron." },
  { id: "ch10-019", chapter: "10", topic: "Cell respiration", question: "In aerobic respiration of glucose, what is oxidized and what is reduced?", choices: ["Glucose is oxidized; oxygen is reduced", "Glucose is reduced; oxygen is oxidized", "Both are oxidized", "Both are reduced"], answer: 0, explanation: "C6H12O6 + 6O2 -> 6CO2 + 6H2O + ATP." },
  { id: "ch10-020", chapter: "10", topic: "Cell respiration", question: "What is the terminal electron acceptor in aerobic respiration?", choices: ["Oxygen", "Nitrate", "Pyruvate", "NAD+"], answer: 0, explanation: "Anaerobic respiration uses other acceptors, such as nitrate or sulfate." },
  { id: "ch10-021", chapter: "10", topic: "Cell respiration", question: "Where does glycolysis occur?", choices: ["In the cytoplasm", "In the mitochondrial matrix", "In the inner mitochondrial membrane", "In the nucleus"], answer: 0, explanation: "Glycolysis takes place in the cytoplasm in both prokaryotes and eukaryotes." },
  { id: "ch10-022", chapter: "10", topic: "Cell respiration", question: "What is the big-picture result of glycolysis?", choices: ["Glucose is split into 2 pyruvate, with a net gain of 2 ATP and 2 NADH", "Glucose is converted to ethanol only", "36 ATP are produced", "Oxygen is consumed"], answer: 0, explanation: "Glycolysis produces pyruvate, a small net ATP, and NADH." },
  { id: "ch10-023", chapter: "10", topic: "Cell respiration", question: "Where does the Krebs cycle occur in eukaryotes?", choices: ["Mitochondrial matrix", "Cytoplasm", "Inner mitochondrial membrane", "Golgi apparatus"], answer: 0, explanation: "In prokaryotes it occurs in the cytoplasm." },
  { id: "ch10-024", chapter: "10", topic: "Cell respiration", question: "Which molecule is released as waste during the Krebs cycle?", choices: ["CO2", "O2", "Ethanol", "Lactic acid"], answer: 0, explanation: "Carbon atoms from glucose are released as CO2 while NADH and FADH2 are produced." },
  { id: "ch10-025", chapter: "10", topic: "Cell respiration", question: "Where is the electron transport chain (ETC) located in eukaryotes versus prokaryotes?", choices: ["Inner mitochondrial membrane; plasma membrane", "Cytoplasm; nucleus", "Mitochondrial matrix; ribosomes", "Nucleus; cell wall"], answer: 0, explanation: "The ETC is membrane-bound: inner mitochondrial membrane in eukaryotes, plasma membrane in prokaryotes." },
  { id: "ch10-026", chapter: "10", topic: "Cell respiration", question: "What happens to H+ ions during the ETC?", choices: ["They are pumped across the membrane, building a gradient", "They are converted to CO2", "They are released as waste in the cytoplasm", "They are destroyed"], answer: 0, explanation: "The H+ gradient stores energy used for ATP synthesis." },
  { id: "ch10-027", chapter: "10", topic: "Cell respiration", question: "Chemiosmosis is:", choices: ["Movement of H+ down their gradient through ATP synthase to make ATP", "Fermentation of glucose", "Breakdown of ATP", "Diffusion of water"], answer: 0, explanation: "The proton gradient powers ATP synthase." },
  { id: "ch10-028", chapter: "10", topic: "Cell respiration", question: "Which enzyme synthesizes ATP during chemiosmosis, and what powers it?", choices: ["ATP synthase, powered by the H+ gradient", "Hexokinase, powered by glucose", "DNA polymerase, powered by NADH", "Catalase, powered by oxygen"], answer: 0, explanation: "ATP synthase uses the proton motive force." },
  { id: "ch10-029", chapter: "10", topic: "Fermentation", question: "Which statement about fermentation is correct?", choices: ["It uses glycolysis but no ETC, chemiosmosis, or ATP synthase, and yields little ATP", "It uses the ETC and yields about 36 ATP", "It requires oxygen", "It occurs only in eukaryotes"], answer: 0, explanation: "Fermentation regenerates NAD+ so glycolysis can continue." },
  { id: "ch10-030", chapter: "10", topic: "Fermentation", question: "Which pairs the fermentation pathway with its waste product(s)?", choices: ["Lactic acid fermentation produces lactic acid; ethanol fermentation produces ethanol and CO2", "Lactic acid fermentation produces ethanol", "Ethanol fermentation produces only lactic acid", "Both produce only CO2"], answer: 0, explanation: "Lactic acid bacteria make lactic acid; yeast make ethanol and CO2." },
  { id: "ch10-031", chapter: "10", topic: "Fermentation", question: "Which microbes perform ethanol fermentation and are used for baking and brewing?", choices: ["Yeast", "Lactic acid bacteria", "Protozoa", "Helminths"], answer: 0, explanation: "Yeast CO2 makes dough rise; ethanol is the product in brewing." },
  { id: "ch10-032", chapter: "10", topic: "Fermentation", question: "Lactic acid bacteria are useful in:", choices: ["Yogurt and cheese production and the human microbiome", "Brewing beer", "Producing antibiotics", "Causing malaria"], answer: 0, explanation: "Lactobacillus and relatives are beneficial in food and the microbiome." },
  { id: "ch10-033", chapter: "10", topic: "Fermentation", question: "Streptococcus pyogenes causes:", choices: ["Strep throat", "Dental caries", "Acne", "Candidiasis"], answer: 0, explanation: "S. mutans, not S. pyogenes, is the main cause of tooth decay." },
  { id: "ch10-034", chapter: "10", topic: "Fermentation", question: "How do bacteria such as Streptococcus mutans cause tooth decay?", choices: ["They ferment sugars into lactic acid, which dissolves tooth enamel", "They digest enamel with toxins directly", "They produce ethanol", "They infect the pulp only"], answer: 0, explanation: "Acid from fermentation demineralizes enamel." },
  { id: "ch10-035", chapter: "10", topic: "Fermentation", question: "Candidiasis is caused by:", choices: ["A yeast (Candida)", "A protozoan", "A helminth", "A Gram-negative bacterium"], answer: 0, explanation: "Candida albicans causes thrush and yeast infections." },
  { id: "ch10-036", chapter: "10", topic: "Fermentation", question: "Propionibacterium is associated with which condition?", choices: ["Acne", "Strep throat", "Tooth decay", "Botulism"], answer: 0, explanation: "Propionibacterium (now Cutibacterium) acnes lives in hair follicles and contributes to acne." },

  // ---------------- Chapter 10 — From lecture slides (Ch 10 PowerPoint) ----------------
  { id: "ch10-037", chapter: "10", topic: "Metabolism basics", question: "Anabolism is best described as:", choices: ["Biosynthesis that forms covalent bonds by dehydration synthesis and requires energy (endergonic)", "Degradation that breaks covalent bonds by hydrolysis and releases energy", "Fermentation only", "Respiration only"], answer: 0, explanation: "Catabolism is degradation (hydrolytic, exergonic) and its energy drives anabolic reactions." },
  { id: "ch10-038", chapter: "10", topic: "Metabolism basics", question: "Catabolic reactions are described as:", choices: ["Exergonic: they break bonds and release more energy than they consume", "Endergonic: they require ATP", "Dehydration synthesis reactions", "Always forming proteins"], answer: 0, explanation: "Catabolism releases energy, which can be captured as ATP." },
  { id: "ch10-039", chapter: "10", topic: "ATP", question: "How many phosphate groups does ATP contain?", choices: ["Three", "One", "Two", "Four"], answer: 0, explanation: "ATP is adenosine triphosphate; ADP has two and AMP has one." },
  { id: "ch10-040", chapter: "10", topic: "Enzymes", question: "Enzymes are mostly:", choices: ["Proteins that speed up reactions without being permanently altered (a few are RNA)", "Lipids that store energy", "Sugars that fuel reactions", "DNA molecules"], answer: 0, explanation: "A characteristic 3D shape is required for their function." },
  { id: "ch10-041", chapter: "10", topic: "Enzymes", question: "Many enzyme names end with which suffix?", choices: ["-ase", "-ose", "-itis", "-cide"], answer: 0, explanation: "For example, sucrase breaks down sucrose." },
  { id: "ch10-042", chapter: "10", topic: "Enzymes", question: "Sucrase splits sucrose into glucose and fructose. What type of reaction is this?", choices: ["Catabolism", "Anabolism", "Dehydration synthesis", "Redox only"], answer: 0, explanation: "A larger molecule is broken down by hydrolysis." },
  { id: "ch10-043", chapter: "10", topic: "Enzymes", question: "What is a substrate?", choices: ["The substance an enzyme acts on", "The enzyme's cofactor", "The product of the reaction", "An inhibitor"], answer: 0, explanation: "Enzymes show specificity, acting on only one substrate." },
  { id: "ch10-044", chapter: "10", topic: "Enzymes", question: "The active site of an enzyme is:", choices: ["The region that interacts with the substrate", "The region where inhibitors never bind", "The cofactor", "The product"], answer: 0, explanation: "Binding is by induced fit." },
  { id: "ch10-045", chapter: "10", topic: "Enzymes", question: "A substrate fits into an enzyme's active site via:", choices: ["An induced fit mechanism", "A rigid lock and key mechanism", "An irreversible bond", "Hydrolysis"], answer: 0, explanation: "The active site changes shape slightly to fit the substrate." },
  { id: "ch10-046", chapter: "10", topic: "Enzymes", question: "True or false: the shape of an enzyme is the same after a reaction as before it.", choices: ["True", "False", "True only for allosteric enzymes", "False for all enzymes"], answer: 0, explanation: "Enzymes are not permanently altered, so they can be reused." },
  { id: "ch10-047", chapter: "10", topic: "Enzymes", question: "Roughly how fast can an enzyme convert substrate to product?", choices: ["Thousands to millions of substrate molecules per second", "One molecule per hour", "One molecule per minute", "Ten molecules per day"], answer: 0, explanation: "Enzymes are extremely efficient catalysts." },
  { id: "ch10-048", chapter: "10", topic: "Enzymes", question: "How do enzymes speed up reactions?", choices: ["By lowering activation energy, so more molecules reach it", "By raising the temperature", "By adding energy to the reaction", "By being consumed"], answer: 0, explanation: "They increase the likelihood that a reaction occurs." },
  { id: "ch10-049", chapter: "10", topic: "Enzymes", question: "What is an example of an ion cofactor, and what does it do?", choices: ["Mg2+ or Zn2+; forms a bridge between substrate and enzyme", "NAD+; carries electrons", "Glucose; provides energy", "ATP; stores energy"], answer: 0, explanation: "Ion cofactors include Fe2+, Zn2+, Mg2+, and Ca2+." },
  { id: "ch10-050", chapter: "10", topic: "Enzymes", question: "How does a coenzyme differ from other cofactors?", choices: ["It is an organic cofactor that carries a chemical group (such as H+, electrons, or CO2) from one substrate to another", "It is a metal ion", "It is a protein", "It is an inhibitor"], answer: 0, explanation: "Examples are NAD+, NADP+, FAD, and coenzyme A; many derive from B vitamins such as niacin." },
  { id: "ch10-051", chapter: "10", topic: "Enzymes", question: "Which coenzyme is used in catabolic reactions and which in anabolic reactions?", choices: ["NAD+ in catabolic; NADP+ in anabolic", "NADP+ in catabolic; NAD+ in anabolic", "FAD in both", "ATP in both"], answer: 0, explanation: "Both are derived from niacin." },
  { id: "ch10-052", chapter: "10", topic: "Enzymes", question: "Coenzyme A is important in which pathway?", choices: ["The Krebs cycle", "Glycolysis only", "Ethanol fermentation only", "DNA replication only"], answer: 0, explanation: "Acetyl CoA feeds the Krebs cycle." },
  { id: "ch10-053", chapter: "10", topic: "Enzymes", question: "What is the optimal temperature range for the enzymes of most human pathogens?", choices: ["35 to 40 C", "20 to 25 C", "50 to 55 C", "70 to 80 C"], answer: 0, explanation: "A typical human enzyme's optimum is about 37 C; thermophilic bacteria have enzymes with optima around 77 C." },
  { id: "ch10-054", chapter: "10", topic: "Enzymes", question: "Which can cause an enzyme to denature?", choices: ["Heat, extreme pH, certain metals, alcohol, and UV radiation", "Adding substrate", "Adding water", "Normal body temperature"], answer: 0, explanation: "Denaturation is loss of protein structure and may be reversible." },
  { id: "ch10-055", chapter: "10", topic: "Enzymes", question: "Why can a slight fever benefit someone with a bacterial infection?", choices: ["Higher temperatures push pathogen enzymes away from their optimum, slowing growth", "It kills all bacteria instantly", "It increases the pathogen's growth", "It has no effect"], answer: 0, explanation: "Raised temperature can also support the immune response." },
  { id: "ch10-056", chapter: "10", topic: "Enzymes", question: "Why does pH change enzyme activity?", choices: ["H+ and OH- compete with ions in ionic bonds, changing protein shape", "pH changes the enzyme's DNA", "pH adds new substrates", "pH makes enzymes bigger"], answer: 0, explanation: "Each enzyme has an optimum pH, for example pepsin in the stomach and trypsin in the intestine." },
  { id: "ch10-057", chapter: "10", topic: "Enzymes", question: "Why does enzyme activity level off at high substrate concentrations?", choices: ["All active sites are full (saturation), so enzyme amount becomes limiting", "The substrate is destroyed", "The enzyme denatures", "The temperature drops"], answer: 0, explanation: "Enzyme activity does not always increase as substrate increases." },
  { id: "ch10-058", chapter: "10", topic: "Enzymes", question: "A competitive inhibitor:", choices: ["Resembles the substrate and binds to the active site", "Binds to a regulatory site", "Is also called an allosteric inhibitor", "Does not affect enzyme activity"], answer: 0, explanation: "It competes with the substrate for the active site." },
  { id: "ch10-059", chapter: "10", topic: "Enzymes", question: "A noncompetitive (allosteric) inhibitor:", choices: ["Does not resemble the substrate and binds to a regulatory (allosteric) site, changing the enzyme's shape", "Binds the active site", "Resembles the substrate", "Is a coenzyme"], answer: 0, explanation: "The shape change reduces the enzyme's activity." },
  { id: "ch10-060", chapter: "10", topic: "Enzymes", question: "Nevirapine inhibits HIV reverse transcriptase by binding outside the active site. It is a(n):", choices: ["Allosteric (noncompetitive) inhibitor", "Competitive inhibitor", "Coenzyme", "Substrate"], answer: 0, explanation: "Binding at a regulatory site changes the enzyme's shape." },
  { id: "ch10-061", chapter: "10", topic: "Redox", question: "OIL RIG stands for:", choices: ["Oxidation Is Loss, Reduction Is Gain (of electrons)", "Oxygen In Last, Reduction In Glycolysis", "Oxidation Is Gain, Reduction Is Loss", "Only ATP is Lost"], answer: 0, explanation: "When an electron is exchanged with a proton, oxidation is loss of H and reduction is gain of H." },
  { id: "ch10-062", chapter: "10", topic: "Redox", question: "A molecule that gains one or more electrons is:", choices: ["Reduced", "Oxidized", "Unchanged", "Hydrolyzed"], answer: 0, explanation: "Electrons are negative, so gaining them reduces the overall charge." },
  { id: "ch10-063", chapter: "10", topic: "Redox", question: "Dehydrogenation (removal of a hydrogen atom with its electron) is a(n):", choices: ["Oxidation", "Reduction", "Hydrolysis", "Fermentation"], answer: 0, explanation: "Loss of H counts as oxidation." },
  { id: "ch10-064", chapter: "10", topic: "Redox", question: "Which of the pair NAD+/NADH is the reduced form?", choices: ["NADH", "NAD+", "Both", "Neither"], answer: 0, explanation: "NADH is electron-rich; NAD+ is electron-poor." },
  { id: "ch10-065", chapter: "10", topic: "Redox", question: "NAD+ and FAD are best compared to:", choices: ["Empty shuttles that pick up electrons; NADH and FADH2 are full shuttles that drop them off", "Full shuttles that drop off electrons", "Enzymes that make ATP", "Terminal electron acceptors"], answer: 0, explanation: "Reduced coenzymes donate electrons to the ETC." },
  { id: "ch10-066", chapter: "10", topic: "Respiration vs fermentation", question: "Cell respiration and fermentation are pathways that:", choices: ["Oxidize chemical energy sources like glucose to make ATP", "Build glucose using light", "Replicate DNA", "Make proteins"], answer: 0, explanation: "Many microbial tests and differential media focus on these processes." },
  { id: "ch10-067", chapter: "10", topic: "Cell respiration", question: "In cell respiration the terminal electron acceptor is reduced. If the acceptor is O2 the process is ___, and if it is another molecule the process is ___.", choices: ["Aerobic respiration; anaerobic respiration", "Anaerobic respiration; aerobic respiration", "Fermentation; respiration", "Respiration; photosynthesis"], answer: 0, explanation: "The summary reaction is C6H12O6 + 6 O2 -> 6 CO2 + 6 H2O + ATP." },
  { id: "ch10-068", chapter: "10", topic: "Cell respiration", question: "In the aerobic respiration summary reaction, glucose undergoes ___ to form CO2, and O2 undergoes ___ to form H2O.", choices: ["Oxidation; reduction", "Reduction; oxidation", "Oxidation; oxidation", "Reduction; reduction"], answer: 0, explanation: "The reaction is catabolic." },
  { id: "ch10-069", chapter: "10", topic: "Cell respiration", question: "Central metabolism consists of:", choices: ["Glycolysis plus the Krebs cycle", "Glycolysis plus the ETC", "Fermentation plus chemiosmosis", "The ETC only"], answer: 0, explanation: "Electrons from glucose are transferred to NAD+ or FAD to make NADH or FADH2." },
  { id: "ch10-070", chapter: "10", topic: "Cell respiration", question: "In prokaryotes, how many total ATP are made per glucose in aerobic respiration, and from where?", choices: ["About 38: 4 from central metabolism and 34 from chemiosmosis", "2 from glycolysis only", "About 100 from the Krebs cycle", "38 from glycolysis"], answer: 0, explanation: "Eukaryotes get about 36 because energy is lost transferring NADH and FADH2 across the membrane." },
  { id: "ch10-071", chapter: "10", topic: "Cell respiration", question: "What is glycolysis?", choices: ["The 'sugar splitting' pathway that splits a 6C sugar into two 3C molecules and is used in most living cells", "The ETC", "A fermentation pathway only", "The Krebs cycle"], answer: 0, explanation: "It involves 10 reactions, each needing a different enzyme." },
  { id: "ch10-072", chapter: "10", topic: "Cell respiration", question: "True or false: glycolysis is aerobic.", choices: ["False; it does not require O2", "True", "True only in eukaryotes", "True only in prokaryotes"], answer: 0, explanation: "Glycolysis is followed by respiration or fermentation." },
  { id: "ch10-073", chapter: "10", topic: "Cell respiration", question: "During glycolysis, which molecule receives the electrons from oxidized glucose?", choices: ["NAD+, becoming NADH", "NADH, becoming NAD+", "Oxygen", "ATP"], answer: 0, explanation: "The net gain is 2 ATP and 2 NADH." },
  { id: "ch10-074", chapter: "10", topic: "Cell respiration", question: "What happens to pyruvate if the cell can respire and has its terminal electron acceptor?", choices: ["It is respired; otherwise it is fermented", "It is always fermented", "It is excreted unchanged", "It is converted to glucose"], answer: 0, explanation: "The pyruvate's fate depends on whether the cell can respire and has a TEA." },
  { id: "ch10-075", chapter: "10", topic: "Cell respiration", question: "The Krebs cycle is also called the:", choices: ["Citric acid cycle or TCA cycle", "Calvin cycle", "Urea cycle", "Pentose pathway"], answer: 0, explanation: "It gradually releases energy through electron transfer to NAD+ and FAD." },
  { id: "ch10-076", chapter: "10", topic: "Cell respiration", question: "How many turns of the Krebs cycle occur per glucose, and why?", choices: ["2, because glucose makes 2 pyruvate", "1", "10", "38"], answer: 0, explanation: "Each turn handles one acetyl CoA from one pyruvate." },
  { id: "ch10-077", chapter: "10", topic: "Cell respiration", question: "Per glucose, the Krebs cycle (both turns) directly yields about:", choices: ["2 ATP, 6 NADH, 2 FADH2, and 4 CO2", "38 ATP", "2 NADH only", "No CO2"], answer: 0, explanation: "The 4 ATP made in central metabolism overall are meager; most ATP comes from chemiosmosis." },
  { id: "ch10-078", chapter: "10", topic: "Cell respiration", question: "NADH and FADH2 are collectively called:", choices: ["Reduced coenzymes", "Oxidized coenzymes", "Terminal electron acceptors", "Substrates"], answer: 0, explanation: "They donate electrons to the ETC." },
  { id: "ch10-079", chapter: "10", topic: "Cell respiration", question: "The ETC is a series of:", choices: ["Proteins and lipid-soluble molecules carrying out redox reactions", "Enzymes that digest proteins", "Ribosomes", "Plasmids"], answer: 0, explanation: "Energy released drives H+ pumps, creating a proton motive force." },
  { id: "ch10-080", chapter: "10", topic: "Cell respiration", question: "What does the last carrier of the ETC donate electrons to?", choices: ["The terminal electron acceptor", "NAD+", "Glucose", "ATP synthase"], answer: 0, explanation: "In aerobic organisms the last carrier is cytochrome oxidase; the acceptor is always a molecule from the environment, not part of the ETC." },
  { id: "ch10-081", chapter: "10", topic: "Cell respiration", question: "The oxidase test detects which enzyme?", choices: ["Cytochrome c oxidase", "Catalase", "Lactase", "Transpeptidase"], answer: 0, explanation: "Purple means oxidase positive, as in Neisseria gonorrhoeae, Pseudomonas aeruginosa, and Vibrio cholerae; Enterobacteriaceae such as E. coli are negative." },
  { id: "ch10-082", chapter: "10", topic: "Cell respiration", question: "Where are H+ pumped by the ETC in bacteria versus eukaryotes?", choices: ["Outside the cell in bacteria; the intermembrane space in eukaryotes", "Into the nucleus in both", "Into the cytoplasm in both", "Into the Golgi in eukaryotes"], answer: 0, explanation: "This builds a high H+ concentration on one side of the membrane." },
  { id: "ch10-083", chapter: "10", topic: "Cell respiration", question: "ATP synthase uses which energy source to make ATP?", choices: ["The H+ gradient (proton motive force)", "Light", "Glucose directly", "Oxygen directly"], answer: 0, explanation: "H+ flows through ATP synthase, a process called chemiosmosis." },
  { id: "ch10-084", chapter: "10", topic: "Cell respiration", question: "Approximately how many ATP result from the ETC and chemiosmosis for each NADH and each FADH2?", choices: ["3 ATP per NADH; 2 ATP per FADH2", "1 ATP per NADH; 3 per FADH2", "10 ATP per NADH; 5 per FADH2", "0 for both"], answer: 0, explanation: "FADH2 donates electrons later in the chain, so it yields less." },
  { id: "ch10-085", chapter: "10", topic: "Cell respiration", question: "Which are examples of terminal electron acceptors in anaerobic respiration?", choices: ["NO3-, SO4 2-, and CO2", "O2 only", "Glucose", "Pyruvate"], answer: 0, explanation: "Nitrate can be reduced to N2, sulfate to H2S, and CO2 to CH4; yields are 2 to 36 ATP per glucose." },
  { id: "ch10-086", chapter: "10", topic: "Fermentation", question: "Which statement about fermentation is correct?", choices: ["It involves incomplete oxidation, no external TEA, and can occur even when O2 is present", "It requires O2", "It uses the ETC", "It yields 38 ATP"], answer: 0, explanation: "O2 is not required or used." },
  { id: "ch10-087", chapter: "10", topic: "Fermentation", question: "In fermentation, who gains the electrons from NADH?", choices: ["Pyruvate or a pyruvate derivative", "The ETC", "Oxygen", "ATP synthase"], answer: 0, explanation: "This regenerates NAD+ so glycolysis can continue." },
  { id: "ch10-088", chapter: "10", topic: "Fermentation", question: "How many ATP does fermentation typically produce per glucose, and from what?", choices: ["2 ATP, made during glycolysis", "38 ATP, from chemiosmosis", "4 ATP, from the Krebs cycle", "0 ATP"], answer: 0, explanation: "There is no Krebs cycle, ETC, PMF, or chemiosmosis, so no extra ATP." },
  { id: "ch10-089", chapter: "10", topic: "Fermentation", question: "What kind of waste do fermentation pathways typically release?", choices: ["Acids and sometimes gases", "Only water", "Only oxygen", "Only CO2"], answer: 0, explanation: "Phenol red turns yellow when acid is made, and a Durham tube captures gas." },
  { id: "ch10-090", chapter: "10", topic: "Fermentation", question: "In a phenol red broth, what do yellow color and a gas bubble in the Durham tube indicate?", choices: ["Acid and gas were produced by fermentation", "No fermentation", "Aerobic respiration", "Contamination only"], answer: 0, explanation: "Phenol red is yellow when acidic and red or pink when not acidic." },
  { id: "ch10-091", chapter: "10", topic: "Fermentation", question: "Lactic acid bacteria are:", choices: ["Gram-positive bacteria that all perform lactic acid fermentation", "Gram-negative bacteria", "Fungi", "Protozoa"], answer: 0, explanation: "Beneficial members include Lactobacillus and Streptococcus thermophilus; pathogenic ones include Enterococcus, S. pyogenes, and S. mutans." },
  { id: "ch10-092", chapter: "10", topic: "Fermentation", question: "Which are beneficial uses of lactic acid bacteria?", choices: ["Probiotics, human microbiome, food production, and food preservation", "Causing tooth decay", "Causing strep throat", "Making antibiotics only"], answer: 0, explanation: "They live in the intestines, mouth, vagina, and skin." },
  { id: "ch10-093", chapter: "10", topic: "Fermentation", question: "Which microbes primarily perform ethanol fermentation?", choices: ["Yeasts", "Lactic acid bacteria", "Protozoa", "Viruses"], answer: 0, explanation: "Beneficial yeasts are used in food production and industry." },
  { id: "ch10-094", chapter: "10", topic: "Fermentation", question: "Candida albicans is associated with which condition, and which species is an emerging multidrug-resistant concern?", choices: ["Candidiasis; Candida auris", "Strep throat; Streptococcus mutans", "Acne; Propionibacterium", "Malaria; Plasmodium"], answer: 0, explanation: "Candidiasis can be overgrowth on skin, mouth, or vagina, or bloodstream infection in immunocompromised patients." },
  { id: "ch10-095", chapter: "10", topic: "Fermentation", question: "True or false: fermentation can occur in the presence of oxygen.", choices: ["True", "False", "True only for yeast", "False for bacteria"], answer: 0, explanation: "Fermentation does not require or use O2, but it is not prevented by it." },
  { id: "ch10-096", chapter: "10", topic: "Respiration vs fermentation", question: "Which type of microbe typically grows fastest?", choices: ["One using aerobic respiration", "One using anaerobic respiration", "One using fermentation", "They all grow the same"], answer: 0, explanation: "Aerobic respiration yields the most ATP per glucose." },

  // ---------------- Chapter 11A — Physical Control of Microbes ----------------
  { id: "ch11a-001", chapter: "11A", topic: "Resistance", question: "Which microbial form is generally the most resistant to control measures?", choices: ["Bacterial endospores", "Gram-positive vegetative bacteria", "Enveloped viruses", "Gram-negative vegetative bacteria"], answer: 0, explanation: "Endospores resist heat, chemicals, and radiation better than vegetative cells." },
  { id: "ch11a-002", chapter: "11A", topic: "Terminology", question: "Sterilization is the:", choices: ["Destruction or removal of all microbial life, including endospores", "Reduction of pathogens on living tissue", "Reduction of microbes on inanimate objects only", "Inhibition of growth"], answer: 0, explanation: "Sterilization means no viable microbes of any kind remain." },
  { id: "ch11a-003", chapter: "11A", topic: "Terminology", question: "Disinfection refers to:", choices: ["Destroying pathogens on inanimate objects", "Destroying all microbes including endospores", "Applying chemicals to skin", "Lowering microbial numbers to safe public health levels"], answer: 0, explanation: "Disinfection targets pathogens on objects and may not kill endospores." },
  { id: "ch11a-004", chapter: "11A", topic: "Terminology", question: "Antisepsis (degermination) is:", choices: ["Reducing microbes on living tissue", "Sterilizing instruments", "Cleaning countertops", "Killing endospores"], answer: 0, explanation: "Antiseptics are used on skin and tissue, not inanimate objects." },
  { id: "ch11a-005", chapter: "11A", topic: "Terminology", question: "Decontamination (sanitation) aims to:", choices: ["Lower microbial numbers to a safe level, as in public health settings", "Eliminate every microbe", "Treat infections in patients", "Kill only viruses"], answer: 0, explanation: "Sanitation reduces microbial load but does not necessarily sterilize." },
  { id: "ch11a-006", chapter: "11A", topic: "Terminology", question: "How do -cidal agents differ from -static agents?", choices: ["-cidal agents kill; -static agents inhibit growth", "-cidal agents inhibit growth; -static agents kill", "Both kill microbes", "Both only inhibit viruses"], answer: 0, explanation: "Bactericidal kills bacteria; bacteriostatic prevents their growth." },
  { id: "ch11a-007", chapter: "11A", topic: "Death rate", question: "How do individuals in a microbial population die when exposed to a control agent?", choices: ["At a constant rate (the same proportion per unit time)", "All at the same instant", "Randomly at an increasing rate", "Only after a long delay"], answer: 0, explanation: "Microbial death is exponential, so a constant fraction die each time interval." },
  { id: "ch11a-008", chapter: "11A", topic: "Death rate", question: "Which factor influences the rate of microbial death?", choices: ["Temperature or concentration of the agent, exposure time, and type of microbe", "Color of the container", "Day of the week", "Number of researchers"], answer: 0, explanation: "Other factors include initial population size and the presence of organic matter." },
  { id: "ch11a-009", chapter: "11A", topic: "Cell targets", question: "Which list names the four main categories of cell targets of physical and chemical agents?", choices: ["Cell wall, cell membrane, proteins, and nucleic acids", "Flagella, pili, capsules, and plasmids", "Ribosomes only", "Endospores only"], answer: 0, explanation: "The targets are the cell wall, cell membrane, proteins/enzymes, and nucleic acids." },
  { id: "ch11a-010", chapter: "11A", topic: "Moist heat", question: "How does moist heat kill microbes?", choices: ["It denatures proteins and disrupts membranes", "It dehydrates cells", "It forms thymidine dimers", "It oxidizes DNA"], answer: 0, explanation: "Moist heat coagulates proteins; autoclaving at 121 C and about 15 psi sterilizes." },
  { id: "ch11a-011", chapter: "11A", topic: "Moist heat", question: "Which method uses pressurized steam to achieve sterilization?", choices: ["Autoclave", "Pasteurization", "Boiling", "Refrigeration"], answer: 0, explanation: "Autoclaving reaches temperatures above boiling and kills endospores." },
  { id: "ch11a-012", chapter: "11A", topic: "Moist heat", question: "Boiling water generally does NOT sterilize because:", choices: ["Endospores can survive it", "It is too cold to kill any bacteria", "It does not denature proteins", "It forms thymidine dimers"], answer: 0, explanation: "Boiling reaches 100 C, which does not reliably kill endospores." },
  { id: "ch11a-013", chapter: "11A", topic: "Moist heat", question: "UHT (ultra-high-temperature) treatment of milk uses:", choices: ["Very high heat for a very short time", "Low heat for a long time", "Radiation", "Freezing"], answer: 0, explanation: "UHT is about 134 C for a few seconds, making milk shelf-stable." },
  { id: "ch11a-014", chapter: "11A", topic: "Dry heat", question: "How does dry heat differ from moist heat?", choices: ["It requires higher temperatures and longer times and kills by oxidation", "It works faster at lower temperatures", "It works by denaturing proteins faster", "It is used only on skin"], answer: 0, explanation: "Dry heat (ovens, incineration) is less efficient than moist heat." },
  { id: "ch11a-015", chapter: "11A", topic: "Cold and desiccation", question: "What is the effect of refrigeration on microbes?", choices: ["It slows growth (static) but does not reliably kill them", "It sterilizes", "It kills endospores", "It increases growth"], answer: 0, explanation: "Cold treatment is microbistatic." },
  { id: "ch11a-016", chapter: "11A", topic: "Cold and desiccation", question: "Desiccation (drying) controls microbes by:", choices: ["Removing water needed for growth, which is mostly static", "Forming thymidine dimers", "Denaturing DNA", "Increasing osmotic pressure with sugar"], answer: 0, explanation: "Drying halts growth, but many microbes survive and revive when rehydrated." },
  { id: "ch11a-017", chapter: "11A", topic: "Radiation", question: "Ionizing radiation (gamma rays, X-rays) differs from nonionizing radiation (UV) because it:", choices: ["Penetrates deeply and can sterilize items such as medical supplies", "Only works on surfaces", "Forms thymidine dimers specifically", "Has low energy"], answer: 0, explanation: "Ionizing radiation damages DNA deeply; UV has poor penetration." },
  { id: "ch11a-018", chapter: "11A", topic: "Radiation", question: "How does UV light kill microbes?", choices: ["It forms thymidine dimers in DNA", "It denatures enzymes with steam", "It dissolves the cell wall", "It increases osmotic pressure"], answer: 0, explanation: "Thymidine dimers block DNA replication and transcription." },
  { id: "ch11a-019", chapter: "11A", topic: "Filtration", question: "What are two advantages of filtration as a microbial control method?", choices: ["It removes microbes from heat-sensitive liquids and air without heat or chemicals", "It kills endospores with heat", "It adds preservatives", "It increases osmotic pressure"], answer: 0, explanation: "Filters trap microbes by pore size; HEPA filters clean air." },
  { id: "ch11a-020", chapter: "11A", topic: "Osmotic pressure", question: "How does adding high concentrations of salt or sugar control microbial growth?", choices: ["It draws water out of cells by osmosis (plasmolysis)", "It forms thymidine dimers", "It denatures proteins with heat", "It filters the microbes out"], answer: 0, explanation: "High solute levels dehydrate cells and are used in preserving foods such as jams and cured meats." },

  // ---------------- Chapter 11A — From lecture slides (Ch 11 Part 1: Physical Methods) ----------------
  { id: "ch11a-021", chapter: "11A", topic: "Terminology", question: "Which best describes sterilization?", choices: ["Removal or destruction of all life, including endospores and viruses, mostly on inanimate objects", "Removal of most vegetative microbes from living tissue", "Mechanical removal of microbes only", "Slowing the growth of microbes"], answer: 0, explanation: "Sterilization is usually done with heat, though certain chemicals and filtration also work." },
  { id: "ch11a-022", chapter: "11A", topic: "Terminology", question: "Commercial sterilization of canned food is designed to destroy the spores of which bacterium?", choices: ["Clostridium botulinum", "Bacillus anthracis", "Clostridium tetani", "Escherichia coli"], answer: 0, explanation: "C. botulinum causes botulism; commercial sterilization destroys its spores while preserving food quality." },
  { id: "ch11a-023", chapter: "11A", topic: "Terminology", question: "Which statement correctly describes disinfection?", choices: ["It removes or destroys most vegetative microbes on inanimate surfaces but not endospores", "It destroys all life, including endospores", "It is used only on living tissue", "It only slows growth"], answer: 0, explanation: "Disinfectants are usually chemicals, but radiation or boiling water/steam can also disinfect." },
  { id: "ch11a-024", chapter: "11A", topic: "Terminology", question: "Antisepsis (degermination) differs from disinfection because antisepsis is applied to:", choices: ["Living tissue", "Inanimate surfaces", "Culture media", "Air only"], answer: 0, explanation: "An antiseptic inhibits or destroys microbes on living tissue." },
  { id: "ch11a-025", chapter: "11A", topic: "Terminology", question: "What is the difference between sepsis and asepsis?", choices: ["Sepsis is microbial growth in the blood; asepsis is the absence of microbial contamination", "Sepsis is the absence of contamination; asepsis is growth in blood", "Both mean sterilization", "Both mean disinfection"], answer: 0, explanation: "The terms are opposites." },
  { id: "ch11a-026", chapter: "11A", topic: "Terminology", question: "Decontamination (sanitization) is best described as:", choices: ["Mechanical removal of microbes from animate or inanimate objects to lower microbial loads", "Complete destruction of endospores", "Treatment of infections", "Freezing microbes"], answer: 0, explanation: "It reduces spoilage and the risk of infection." },
  { id: "ch11a-027", chapter: "11A", topic: "Terminology", question: "A sporicide is an agent that:", choices: ["Kills endospores and can act as a sterilant", "Only slows endospore growth", "Kills only vegetative cells", "Kills only viruses"], answer: 0, explanation: "-cide means kill, for example germicide, virucide, and fungicide." },
  { id: "ch11a-028", chapter: "11A", topic: "Terminology", question: "What happens when a bacteriostatic agent is removed?", choices: ["Growth resumes", "The bacteria stay dead", "The bacteria form endospores", "The bacteria are sterilized"], answer: 0, explanation: "-stat agents inhibit growth but do not kill; refrigeration is an example." },
  { id: "ch11a-029", chapter: "11A", topic: "Death rate", question: "Which of these factors influences the death rate of microbes exposed to a control agent?", choices: ["Exposure time, number of microbes, microbe characteristics, and the control agent", "Only the color of the container", "Only the time of day", "None; all microbes die equally"], answer: 0, explanation: "Heat and chemical exposure cause death at a constant rate for a given set of conditions." },
  { id: "ch11a-030", chapter: "11A", topic: "Death rate", question: "In which bacterial growth phase are cells most susceptible to microbicidal agents?", choices: ["Log phase", "Lag phase", "Stationary phase", "Death phase"], answer: 0, explanation: "Actively dividing cells are the most vulnerable." },
  { id: "ch11a-031", chapter: "11A", topic: "Cell targets", question: "Which are the four cell targets of antimicrobial agents named in lecture?", choices: ["Cell wall, cell membrane, nucleic acid synthesis, and proteins", "Ribosomes, flagella, pili, and capsules", "Plasmids, endospores, nucleoid, and cytoplasm", "Mitochondria, nucleus, Golgi, and ER"], answer: 0, explanation: "Different physical and chemical agents target different structures." },
  { id: "ch11a-032", chapter: "11A", topic: "Physical methods", question: "Which list names the physical methods of microbial control covered?", choices: ["Moist heat, dry heat, filtration, low temperature, desiccation, pressure, osmotic pressure, and radiation", "Antibiotics, vaccines, and probiotics", "Phenols, alcohols, and halogens", "Staining, culturing, and microscopy"], answer: 0, explanation: "Phenols, alcohols, and halogens are chemical agents." },
  { id: "ch11a-033", chapter: "11A", topic: "Moist heat", question: "What is the mechanism by which moist heat kills microbes?", choices: ["Denaturation and coagulation of proteins", "Formation of thymine dimers", "Plasmolysis", "Filtering"], answer: 0, explanation: "Moist heat denatures proteins, including enzymes." },
  { id: "ch11a-034", chapter: "11A", topic: "Moist heat", question: "Boiling (100 C at sea level) for about 10 minutes kills which of the following?", choices: ["Vegetative cells, some viruses, and fungi, but not endospores", "All microbes including endospores", "Only viruses", "Nothing"], answer: 0, explanation: "Boiling does not kill all viruses and does not kill endospores, so it does not sterilize." },
  { id: "ch11a-035", chapter: "11A", topic: "Moist heat", question: "What are the standard autoclave conditions?", choices: ["121 C for 15 minutes with steam under pressure", "100 C for 10 minutes", "72 C for 15 seconds", "170 C for 2 hours"], answer: 0, explanation: "Sterilization requires temperatures above 100 C, which pressure makes possible; the autoclave is the preferred method of sterilization." },
  { id: "ch11a-036", chapter: "11A", topic: "Moist heat", question: "True or false: all materials can be autoclaved.", choices: ["False; heat- or moisture-sensitive materials can be damaged", "True", "True, but only plastics", "True, but only liquids"], answer: 0, explanation: "Heat-sensitive items need another method such as filtration or gas sterilization." },
  { id: "ch11a-037", chapter: "11A", topic: "Pasteurization", question: "What is the purpose of pasteurization?", choices: ["Mild heating to kill spoilage microbes and pathogens without damaging the product", "To sterilize completely with no flavor change", "To freeze the product", "To remove proteins"], answer: 0, explanation: "It is used for wine, beer, milk, and yogurt." },
  { id: "ch11a-038", chapter: "11A", topic: "Pasteurization", question: "What are the conditions for HTST pasteurization?", choices: ["72 C for 15 seconds", "134 C for 1-2 seconds", "121 C for 15 minutes", "100 C for 10 minutes"], answer: 0, explanation: "HTST means high temperature, short time." },
  { id: "ch11a-039", chapter: "11A", topic: "Pasteurization", question: "Ultra-high temperature (UHT) treatment uses which conditions?", choices: ["134 C for 1-2 seconds, followed by vacuum cooling", "72 C for 15 seconds", "62 C for 30 minutes", "170 C for 2 hours"], answer: 0, explanation: "UHT is a sterilization process." },
  { id: "ch11a-040", chapter: "11A", topic: "Dry heat", question: "Dry heat kills microbes by:", choices: ["Dehydrating cells and denaturing proteins", "Forming thymine dimers", "Plasmolysis", "Trapping microbes in pores"], answer: 0, explanation: "Examples are direct flaming, incineration, and hot air ovens." },
  { id: "ch11a-041", chapter: "11A", topic: "Dry heat", question: "What are typical conditions for hot air (oven) sterilization?", choices: ["170 C for 2 hours", "121 C for 15 minutes", "72 C for 15 seconds", "100 C for 10 minutes"], answer: 0, explanation: "Dry heat requires higher temperatures and longer times than moist heat." },
  { id: "ch11a-042", chapter: "11A", topic: "Filtration", question: "What pore size is used to filter out bacteria, and what size is needed for viruses?", choices: ["0.22 micrometers for bacteria; 0.01 micrometers for viruses", "10 micrometers for bacteria; 5 for viruses", "0.01 micrometers for bacteria; 0.22 for viruses", "1 millimeter for both"], answer: 0, explanation: "Filters trap microbes larger than their pores and work on liquids or gases." },
  { id: "ch11a-043", chapter: "11A", topic: "Filtration", question: "HEPA filters are used to remove microbes from:", choices: ["Air", "Cell membranes", "Solid food only", "Skin"], answer: 0, explanation: "HEPA stands for high efficiency particulate air." },
  { id: "ch11a-044", chapter: "11A", topic: "Filtration", question: "Which would be the most effective way to sterilize a small amount of liquid containing a very expensive antibiotic?", choices: ["Filtration", "Autoclaving", "Incineration", "UV exposure"], answer: 0, explanation: "Heat would destroy the antibiotic; filtration removes microbes without heat." },
  { id: "ch11a-045", chapter: "11A", topic: "Moist heat", question: "Which would be the most effective way to sterilize a small surgical tool kit?", choices: ["Autoclaving", "Filtration", "UV exposure", "Incineration"], answer: 0, explanation: "Metal tools tolerate heat and steam, and the autoclave is the preferred sterilization method." },
  { id: "ch11a-046", chapter: "11A", topic: "Cold and desiccation", question: "Which of these is bactericidal?", choices: ["Autoclaving", "Refrigeration", "Desiccation", "Low temperature"], answer: 0, explanation: "Low temperature and desiccation are usually bacteriostatic, although they may kill." },
  { id: "ch11a-047", chapter: "11A", topic: "Pressure", question: "How does high pressure act on microbes?", choices: ["It alters protein structure", "It forms thymine dimers", "It dehydrates cells", "It filters them out"], answer: 0, explanation: "Pressure is one of the other physical methods covered." },
  { id: "ch11a-048", chapter: "11A", topic: "Osmotic pressure", question: "How does high osmotic pressure (adding salt or sugar) affect microbes?", choices: ["It causes plasmolysis, shrinking the cell as water leaves", "It causes osmotic lysis", "It forms thymine dimers", "It makes endospores"], answer: 0, explanation: "Hypertonic conditions pull water out of the cells." },
  { id: "ch11a-049", chapter: "11A", topic: "Radiation", question: "True or false: ionizing radiation carries more energy than non-ionizing radiation.", choices: ["True", "False", "True only for UV", "False for gamma rays"], answer: 0, explanation: "Ionizing radiation has a shorter wavelength (under 1 nm) and higher energy." },
  { id: "ch11a-050", chapter: "11A", topic: "Radiation", question: "Which are examples of ionizing radiation?", choices: ["Gamma rays, X-rays, and electron beams", "UV light and visible light", "Microwaves and radio waves", "Infrared and heat"], answer: 0, explanation: "They cause ionization (release of electrons and generation of ions) and have some penetration." },
  { id: "ch11a-051", chapter: "11A", topic: "Radiation", question: "Non-ionizing radiation such as UV light:", choices: ["Has low penetration, so it is used on surfaces, and is absorbed by DNA forming thymine dimers", "Penetrates deeply to sterilize packaged items", "Has a very short wavelength", "Works by filtering"], answer: 0, explanation: "UV also generates free radicals." }
];

